/* Déclic — Anglais B2 (unités 4 à 6). Format : docs/ANGLAIS.md */
(()=>{
// Variantes de réponse : {a|b} donne les deux versions ; A() ajoute les contractions en ’d (had, would) et ’s (is, has)
// que la normalisation de langue.js ne développe pas (I’d = I had / I would, it’s = it is / it has).
const PP='been|known|gone|seen|taken|left|told|had|done|made|got|gotten|come|run|bought|brought|thought|caught|said|met|lost|found|given|forgotten|written|spoken|eaten|driven|fallen|heard|kept|paid|read|sent|spent|won|felt|become|begun|broken|chosen|understood|woken|worn|hidden|stolen|sold|shut|put|set|let|cut|hit|hurt|[a-z]+ed';
const RE=new RegExp(`\\b(I|you|he|she|it|we|they|who|there)( would| had(?= (?:not |never |already |just |only )?(?:${PP})\\b)| is| has(?= (?:not |never |already |just )?(?:${PP})\\b))(?=[ ,.!?])`,'gi');
const X=s=>{ const m=s.match(/\{([^{}]*)\}/); return m?m[1].split('|').flatMap(o=>X(s.replace(m[0],o))):[s]; };
const A=(...L)=>{ const out=[]; L.flatMap(X).forEach(s=>{ s=s.replace(/\s+/g,' ').replace(/ ([.,!?])/g,'$1').trim(); const ms=[...s.matchAll(RE)];
  for(let k=0;k<(1<<ms.length);k++){ let r='',p=0; ms.forEach((x,i)=>{ r+=s.slice(p,x.index)+((k>>i)&1?x[1]+(/would|had/i.test(x[2])?'’d':'’s'):x[0]); p=x.index+x[0].length; }); r+=s.slice(p); if(!out.includes(r)) out.push(r); } }); return out; };

COURS.push(
/* ===================== 4. What if… ===================== */
{subj:'en', sem:'b2', id:'en-b2-conditionals', o:4, h:'What if…', p:'Imagine how the past could have turned out differently, link past events to the present, and express regret and criticism: third and mixed conditionals, <i lang="en">should have</i>, <i lang="en">I wish</i> and <i lang="en">if only</i>.', steps:[
 {kind:'Écoute', h:'The job he turned down',
  p:`<p>By the end of this unit, you’ll be able to talk about how things might have turned out, connect past decisions with your life today, and express regrets and criticism the way native speakers do.</p>
<p>Maya and Tom are having coffee. Tom has just heard some news about a company he very nearly joined. <b>Listen without reading</b>, twice if you need to, then answer. The transcript appears after your answer.</p>
<p><b>Question:</b> why does Tom say it’s “a good thing” that he turned the job down?</p>`,
  audio:[['Maya','Have you seen the news? That little start-up in Edinburgh has just been bought by a tech giant. For two billion pounds!'],['Tom','Don’t remind me. They offered me a job there two years ago, remember? I turned it down.'],['Maya','I know! If you’d taken it, you’d probably be sitting on a pile of shares worth a fortune by now.'],['Tom','Thanks, Maya. That’s really comforting.'],['Maya','Sorry. But why did you say no, in the end?'],['Tom','The salary was lower than what I was earning, and I’d just signed a two-year lease on my flat. If I hadn’t signed it, I might have gone. In hindsight, I should have asked for shares instead of arguing about the salary.'],['Maya','Well, nobody could have predicted it would take off like that.'],['Tom','True. And to be honest, if I’d moved to Edinburgh, I would never have met Clara.'],['Maya','Exactly. And you wouldn’t be planning a wedding right now.'],['Tom','So it’s a good thing I’m such a coward, then.'],['Maya','You’re not a coward, you’re cautious. Although if you weren’t quite so cautious, you’d have said yes on the spot.'],['Tom','Maybe. I still wish I’d at least gone up to visit the office. If only I’d been a bit braver.']], cache:true,
  opts:['Because the start-up went bankrupt soon afterwards.','Because he would never have met his partner, Clara.','Because the salary in Edinburgh was too low to live on.','Because he has since found a better-paid job.'], ans:1,
  why:'Tom says <i lang="en">if I’d moved to Edinburgh, I would never have met Clara</i>, and Maya adds that he <i lang="en">wouldn’t be planning a wedding right now</i>. Turning the job down cost him money, but it was, in a way, a blessing in disguise.'},

 {kind:'Vocabulaire', h:'Turning points and missed chances',
  p:`<p>These collocations and set phrases come up whenever people talk about decisions and what might have been. Tap a line to hear it, then say it aloud. They go into your <b>vocabulary review</b>, which will bring them back tomorrow, then in a few days, just before you forget them.</p>`,
  mots:[['to turn down an offer','refuser une offre','I turned down the offer because the salary was too low.'],['to jump at the chance','sauter sur l’occasion','If they’d asked me, I’d have jumped at the chance.'],['to take off','décoller, connaître un succès soudain','Her career really took off after that film.'],['a turning point','un tournant','Moving to London was a turning point in my life.'],['in hindsight','avec le recul','In hindsight, I should have stayed.'],['to have second thoughts','avoir des doutes (après coup)','She’s having second thoughts about the move.'],['to make the most of something','profiter pleinement de','Make the most of your year abroad.'],['to miss out on something','passer à côté de, rater','I don’t want to miss out on this opportunity.'],['a narrow escape','l’avoir échappé belle','That was a narrow escape: the bridge collapsed an hour later.'],['on the spot','sur-le-champ','They offered me the job on the spot.'],['to be meant to be','être écrit, être le destin','We met by chance. It was meant to be.'],['a blessing in disguise','un mal pour un bien','Losing that job was a blessing in disguise.'],['to let something slip through your fingers','laisser filer quelque chose','Don’t let this chance slip through your fingers.'],['it’s no use crying over spilt milk','inutile de pleurer sur le lait renversé','I lost the deposit, but it’s no use crying over spilt milk.'],['to regret doing something','regretter d’avoir fait','I regret not learning German at school.']],
  note:'<b>Attention :</b> <i lang="en">to regret</i> se construit avec <b>-ing</b> pour un regret sur le passé : <i lang="en">I regret leaving</i> (ou <i lang="en">I regret having left</i>). <i lang="en">I regret to tell you that…</i> sert à annoncer une mauvaise nouvelle, dans une lettre officielle. Et « regretter quelqu’un » se dit <i lang="en">to miss someone</i>.'},

 {kind:'Pratique', h:'Recall: a blessing in disguise',
  p:'Your friend lost her job last year and then found a much better one. Say it in English, starting with <i lang="en">In the end, …</i> <b>Question:</b> how do you say « Finalement, perdre ce travail a été un mal pour un bien. » ?', lab:'Your sentence',
  txt:A('In the end, losing {that|the|this|her} job {was|turned out to be|proved to be} a blessing in disguise.'),
  why:'<i lang="en">In the end, losing that job was (turned out to be) a blessing in disguise.</i> The gerund <i lang="en">losing</i> is the subject of the sentence, as « perdre » is in French.'},

 {kind:'Grammaire', h:'The third conditional: an imaginary past',
  p:`<p>Tom says: <i lang="en">If I hadn’t signed the lease, I might have gone.</i> But he did sign it, and he didn’t go. To talk about a past that never happened, and its imaginary consequences, English uses the <b>third conditional</b>.</p>
<div class="def"><p><b>If + past perfect, would have + past participle</b></p><p><i lang="en">If I <b>had known</b>, I <b>would have come</b>.</i> Both halves are unreal: I didn’t know, so I didn’t come. Replace <i lang="en">would</i> with <b>could have</b> (ability, possibility) or <b>might have</b> (less certain).</p></div>
<div class="idea"><p>Think of it as rewinding a film: you change one past scene and imagine how the next one would have looked. Since both events are finished, both halves look backwards: <i lang="en">had + participle</i> in the condition, <i lang="en">would have + participle</i> in the result. The clauses can swap places: <i lang="en">I would have come if I had known</i> (no comma when <i lang="en">if</i> comes second).</p></div>
<div class="ex"><p><i lang="en">If we had left earlier, we wouldn’t have missed the train.</i> (We left late and missed it.)<br><i lang="en">She might have got the job if she had prepared more.</i><br>In speech: <i lang="en">If I’d known, I’d have come.</i> The first <i lang="en">’d</i> is <b>had</b>, the second is <b>would</b>: <i lang="en">’d</i> + participle = had; <i lang="en">’d</i> + have = would.</p></div>
<div class="warn"><p><b>Piège :</b> le français dit « Si j’avais su, je serais venu », avec le plus-que-parfait après « si », jamais le conditionnel. L’anglais aussi : <b>pas de <i lang="en">would</i> après <i lang="en">if</i></b>. <i lang="en">If I would have known</i> s’entend parfois à l’oral aux États-Unis, mais reste une faute à l’écrit. Et « je serais venu » se dit <i lang="en">I would have come</i>, jamais « I would be come ».</p></div>`,
  audio:'If I had known, I would have come. If we had left earlier, we wouldn’t have missed the train. If I’d known, I’d have come.'},

 {kind:'Grammaire', h:'Mixed conditionals: when past and present meet',
  p:`<p>Maya tells Tom: <i lang="en">If you’d taken that job, you’d probably be sitting on a fortune <b>now</b>.</i> The condition is in the past, but the result is in the present. Real life rarely stays in one time zone, so English lets you <b>mix</b> the two unreal conditionals.</p>
<div class="def"><p><b>Past condition → present result:</b> If + past perfect, would + infinitive.<br><i lang="en">If I had studied medicine, I would be a doctor now.</i></p><p><b>Present (permanent) condition → past result:</b> If + past simple, would have + past participle.<br><i lang="en">If I weren’t so shy, I would have spoken to her at the party.</i></p></div>
<div class="idea"><p>Ask yourself, for each half separately: <b>when</b> is this true? A finished event (a decision, an accident) takes the past perfect; a situation that is still true (your personality, where you live, what you can do) takes the past simple. Then the result: a present consequence takes <i lang="en">would + verb</i>, a past consequence takes <i lang="en">would have + participle</i>. Time words such as <i lang="en">now, today, still</i> or <i lang="en">yesterday, last year</i> are strong clues.</p></div>
<div class="ex"><p><i lang="en">If he hadn’t broken his leg, he would be playing in the final tomorrow.</i><br><i lang="en">If she spoke German, she would have applied for the job in Berlin.</i> (She doesn’t speak German: a permanent fact.)</p></div>
<div class="warn"><p><b>Bonne nouvelle :</b> le français fonctionne exactement pareil. « Si j’avais fait médecine, je <b>serais</b> médecin aujourd’hui » → <i lang="en">I <b>would be</b></i> ; « je <b>serais devenu</b> » → <i lang="en">I <b>would have become</b></i>. Suis ton instinct : conditionnel présent = <i lang="en">would + verbe</i>, conditionnel passé = <i lang="en">would have + participe</i>.</p></div>`,
  audio:'If I had studied medicine, I would be a doctor now. If I weren’t so shy, I would have spoken to her at the party.'},

 {kind:'Méthode', h:'Building a conditional from real facts',
  p:`<p><b>When:</b> you know what really happened and want to imagine the opposite. <b>Why it works:</b> an unreal conditional is simply the facts turned upside down: every positive becomes negative, every negative becomes positive, and each verb moves one step back in time. <b>How:</b></p>
<ul><li>Write down the facts and when each one is true (finished past, or still true now).</li><li>Reverse each fact: <i lang="en">didn’t → had</i>, <i lang="en">did → hadn’t</i>, <i lang="en">am not → were</i>, <i lang="en">am → wouldn’t be</i>.</li><li>Choose the forms: past condition → <i lang="en">had (not) + participle</i>; present condition → past simple; past result → <i lang="en">would (not) have + participle</i>; present result → <i lang="en">would (not) + verb</i>.</li><li>Put the <i lang="en">if</i>-clause first (with a comma) or second (without).</li></ul>`,
  demo:{enonce:'Facts: <i lang="en">I didn’t set an alarm. I overslept and missed my job interview. I’m still looking for a job.</i> Write a third conditional and a mixed conditional.',
   etapes:[{f:'Facts and times: <i lang="en">didn’t set an alarm</i> (past), <i lang="en">missed the interview</i> (past), <i lang="en">still looking for a job</i> (now).',w:'The time of each fact decides its form.'},
    {f:'Reverse them: <i lang="en">didn’t set</i> → <i lang="en">had set</i>; <i lang="en">missed</i> → <i lang="en">wouldn’t have missed</i>; <i lang="en">still looking</i> → <i lang="en">might not be looking</i>.',w:'Negative becomes positive and vice versa.'},
    {f:'Third conditional: <i lang="en">If I had set an alarm, I wouldn’t have missed my interview.</i>',w:'Past condition, past result: <i lang="en">had + participle</i>, then <i lang="en">would have + participle</i>.'},
    {f:'Mixed conditional: <i lang="en">If I hadn’t missed the interview, I might not be looking for a job now.</i>',w:'Past condition, present result: <i lang="en">had + participle</i>, then <i lang="en">might + infinitive</i>. <i lang="en">Might</i>, because getting the job wasn’t certain.'}],
   conclusion:'<i lang="en">If I had set an alarm, I wouldn’t have missed my interview. If I hadn’t missed it, I might not be looking for a job now.</i>'}},

 {kind:'Pratique', h:'Your turn: third conditional',
  p:'Facts: <i lang="en">Anna didn’t revise, so she failed her driving theory test.</i> Write one sentence starting with <i lang="en">If Anna had…</i> <b>Question:</b> what would have happened if things had been different?', lab:'Your sentence',
  txt:A('If Anna had revised, she {would not have failed|would have passed|might have passed|could have passed}{ her driving theory test| her theory test| the theory test| her test| the test| it|}.'),
  why:'Past condition, past result: <i lang="en">If Anna had revised, she wouldn’t have failed her theory test</i> (or <i lang="en">she would have passed it</i>). Never <i lang="en">would</i> in the <i lang="en">if</i>-clause.'},

 {kind:'Pratique', h:'Your turn: past cause, present result',
  p:'Facts: <i lang="en">Leo missed the last train home, so he’s sleeping on his friend’s sofa now.</i> Write a mixed conditional starting with <i lang="en">If Leo hadn’t…</i> and ending with <i lang="en">now</i>. <b>Question:</b> what would be different now?', lab:'Your sentence',
  txt:A('If Leo had not missed the last train{ home|}, he would not be sleeping on {his|a} friend’s sofa now.','If Leo had not missed the last train{ home|}, he would be {sleeping |}{at home|in his own bed} now.'),
  why:'The cause is finished (last night: <i lang="en">hadn’t missed</i>); the result is now (<i lang="en">wouldn’t be sleeping</i>): past perfect, then <i lang="en">would + infinitive</i>.'},

 {kind:'Pratique', h:'Your turn: present cause, past result',
  p:'Facts: <i lang="en">Sophie isn’t very confident, so she didn’t speak up at yesterday’s meeting.</i> Write a mixed conditional starting with <i lang="en">If Sophie were more confident, …</i> <b>Question:</b> what would she have done?', lab:'Your sentence',
  txt:A('If Sophie {were|was} more confident, she would have spoken up{ at yesterday’s meeting| in yesterday’s meeting| at the meeting yesterday| in the meeting yesterday| at the meeting| in the meeting| yesterday|}.'),
  why:'Her lack of confidence is a permanent fact (past simple: <i lang="en">were</i>, or <i lang="en">was</i> in informal speech); the meeting is over (<i lang="en">would have spoken up</i>).'},

 {kind:'Grammaire', h:'Regrets and criticism: should have, I wish, if only',
  p:`<p>Tom says: <i lang="en">I should have asked for shares… I wish I’d at least visited the office. If only I’d been a bit braver.</i> Three ways of looking back at a past you would like to change.</p>
<div class="def"><ul><li><b>should (not) have + past participle</b>: what would have been the right thing to do. It expresses regret (about yourself) or criticism (about others): <i lang="en">You should have told me. I shouldn’t have eaten so much.</i> More formal: <b>ought (not) to have</b>.</li><li><b>I wish + past perfect</b>: a regret about the past. <i lang="en">I wish I had studied harder.</i> (I didn’t.)</li><li><b>If only + past perfect</b>: the same idea, more emotional. <i lang="en">If only we had left five minutes earlier!</i></li></ul></div>
<div class="idea"><p>The past perfect after <i lang="en">wish</i> and <i lang="en">if only</i> works like the <i lang="en">if</i>-clause of a third conditional: it marks the event as unreal. Compare the time zones: <i lang="en">I wish I <b>had</b> a car</i> (now: I don’t have one); <i lang="en">I wish I <b>had had</b> a car last summer</i> (past); <i lang="en">I wish you <b>would stop</b> talking</i> (annoyance: a change you want).</p></div>
<div class="ex"><p><i lang="en">I didn’t back up my files.</i> → <i lang="en">I should have backed up my files. I wish I had backed them up. If only I had backed them up!</i></p></div>
<div class="warn"><p><b>Pièges :</b> « j’aurais dû » se dit <i lang="en">I should have + participe</i>, jamais « I would have must » ni « I should had ». Après <i lang="en">wish</i>, pas de <i lang="en">would have</i> : <i lang="en">I wish I had known</i>, pas « I wish I would have known ». Enfin, <i lang="en">should of</i> est une faute d’orthographe très courante chez les natifs (on entend /ʃʊdəv/) : on écrit <b>should have</b> ou <b>should’ve</b>.</p></div>`,
  audio:'I should have asked for shares. I wish I had visited the office. If only I had been a bit braver!'},

 {kind:'Méthode', h:'From a fact to a regret',
  p:`<p><b>When:</b> you want to express regret, or criticise a past action, in conversation or in writing. <b>Why it works:</b> all three structures look back at a real past fact and imagine its opposite, so the fact has to be <b>reversed</b>, as in a conditional. <b>How:</b></p>
<ul><li>Identify the fact and the person: who did (or didn’t do) what?</li><li>Reverse it: <i lang="en">didn’t go → had gone</i>; <i lang="en">went → hadn’t gone</i>.</li><li>Choose the tone: <i lang="en">should have</i> (a judgement: it was a mistake), <i lang="en">I wish</i> (a personal regret), <i lang="en">If only</i> (strong emotion).</li></ul>`,
  demo:{enonce:'Fact: <i lang="en">Ben shouted at his manager during the meeting, and now he regrets it.</i> Express the regret in three ways, from Ben’s point of view.',
   etapes:[{f:'Fact: <i lang="en">Ben shouted</i> (affirmative, past).',w:'He did shout, so each regret will be negative.'},
    {f:'Judgement: <i lang="en">I shouldn’t have shouted at my manager.</i>',w:'<i lang="en">should not have + participle</i>: it was the wrong thing to do.'},
    {f:'Personal regret: <i lang="en">I wish I hadn’t shouted at my manager.</i>',w:'<i lang="en">wish + past perfect</i>, negative because he did it.'},
    {f:'Strong emotion: <i lang="en">If only I hadn’t lost my temper!</i>',w:'Same form as after <i lang="en">wish</i>; here with a collocation, <i lang="en">to lose your temper</i>.'}],
   conclusion:'<i lang="en">I shouldn’t have shouted at him. I wish I hadn’t. If only I hadn’t lost my temper!</i>'}},

 {kind:'Pratique', h:'Your turn: I wish…',
  p:'Fact: <i lang="en">You didn’t take any photos at your best friend’s wedding.</i> Express your regret with <i lang="en">I wish…</i> <b>Question:</b> what do you wish?', lab:'Your sentence',
  txt:A('I wish I had taken {some |any |more |}{photos|pictures|photographs}{ at my best friend’s wedding| at the wedding| at her wedding| at his wedding|}.'),
  why:'The fact is negative and past, so the wish is affirmative, in the past perfect: <i lang="en">I wish I had taken some photos</i>. <i lang="en">I wish I would have taken</i> is incorrect.'},

 {kind:'Pratique', h:'Your turn: should have',
  p:'Your flatmate left the front door unlocked, and someone stole his bike from the hall. Criticise him with <i lang="en">should</i> or <i lang="en">shouldn’t</i>. <b>Question:</b> what should he have done, or not done?', lab:'Your sentence',
  txt:A('You {should|ought to|really should} have locked the {front |}door.','You {should not|ought not to|really should not} have left the {front |}door unlocked.','You should have locked it.','You should not have left it unlocked.'),
  why:'<i lang="en">You should have locked the door</i> or <i lang="en">You shouldn’t have left it unlocked</i>: <i lang="en">should have + participle</i> criticises a past action.'},

 {kind:'Pratique', h:'Put the regret in order',
  p:'Tap the words in the right order to rebuild what a runner said after a race. <b>Question:</b> what might have happened if she hadn’t fallen?',
  ordre:['If','I','hadn’t','fallen','at','the','last','bend,','I','might','have','won','the','race.'],
  alt:['I might have won the race if I hadn’t fallen at the last bend'],
  why:'<i lang="en">If I hadn’t fallen at the last bend, I might have won the race.</i> A third conditional with <i lang="en">might</i>: she isn’t sure she would have won.'},

 {kind:'Prononciation', h:'Weak forms: should’ve, would’ve, I’d’ve',
  p:`<p>In fast speech, <i lang="en">have</i> after a modal is almost never pronounced in full. It shrinks to /əv/, or even /ə/: <i lang="en">would have</i> → /ˈwʊdəv/, <i lang="en">should have</i> → /ˈʃʊdəv/, <i lang="en">could have</i> → /ˈkʊdəv/. The stress falls on the main verb: <i lang="en">I should’ve <b>told</b> you.</i></p>
<div class="idea"><p>That is why native speakers sometimes write <i lang="en">should of</i> by mistake: they hear /əv/. Listen for the participle that follows: it carries the meaning. In <i lang="en">If I’d known, I’d’ve come</i>, both <i lang="en">’d</i> are tiny: the first is <i lang="en">had</i>, the second <i lang="en">would</i>.</p></div>
<div class="warn"><p><b>Pour les francophones :</b> ne prononce pas chaque mot avec la même force, sinon tu sonnes lent et appliqué. Garde l’énergie pour le verbe principal : <i lang="en">I should’ve <b>called</b></i>, <i lang="en">we could’ve <b>won</b></i>. Et le <i lang="en">h</i> de <i lang="en">have</i> tombe ici : c’est un des rares cas où il ne faut <b>pas</b> l’aspirer.</p></div>
<p>Listen, then say the sentence aloud.</p>`,
  dire:'If I’d known, I’d have come. I should have called you.'},

 {kind:'Vocabulaire', h:'Looking back',
  p:`<p>More expressions for talking about the past with some distance. You’ll meet several of them in the next text.</p>`,
  mots:[['to look back on something','repenser à, revenir sur','Looking back on it, I made the right choice.'],['to dwell on something','ressasser','There’s no point dwelling on your mistakes.'],['to beat yourself up about something','s’en vouloir, se flageller','Don’t beat yourself up about it: everyone forgets things.'],['to come to terms with something','accepter, se faire à','It took her years to come to terms with her decision.'],['what might have been','ce qui aurait pu être','He often thinks about what might have been.'],['to have no regrets','ne rien regretter','I have no regrets about leaving.'],['to learn the hard way','apprendre à ses dépens','I learnt the hard way that you should read the contract.'],['a near miss','un accident évité de justesse, un échec de peu','Fourth place felt like a near miss.']],
  note:'<i lang="en">A narrow escape</i> : on a échappé à un danger. <i lang="en">A near miss</i> : c’est passé tout près (un accident évité, ou un succès manqué de peu). <i lang="en">Learnt</i> (britannique) et <i lang="en">learned</i> (américain, et aussi britannique) sont corrects tous les deux.'},

 {kind:'Lecture', h:'Reading: why silver feels worse than bronze',
  p:`<p>Read this magazine article, then answer. You can also listen to it.</p>
<div class="blk" data-t="Why silver feels worse than bronze"><p lang="en">Every Olympic final ends with three smiling athletes on the podium. Or does it? In the mid-1990s, a team of American psychologists studied television footage of medallists and asked volunteers to rate how happy each athlete looked. The results were surprising: bronze medallists generally looked happier than silver medallists, even though they had performed worse.</p>
<p lang="en">The explanation lies in what researchers call counterfactual thinking: our habit of imagining how things might have turned out. A silver medallist tends to compare upwards: “If I had started a fraction faster, I would have won gold.” A bronze medallist compares downwards: “If I had been a fraction slower, I wouldn’t have got a medal at all.” Same podium, very different “what ifs”.</p>
<p lang="en">Researchers noticed another pattern when they asked people about their biggest regrets. In the short term, we tend to regret things we did: the angry email, the expensive purchase. Over a lifetime, however, the balance shifts. Older people are far more likely to regret what they didn’t do: the course they never took, the friend they never called, the job they turned down. Actions can be explained, apologised for and learnt from; inactions stay open, and the mind keeps rewriting them.</p>
<p lang="en">Psychologists don’t see this as entirely negative. Imagining what might have been helps us learn from our mistakes: a driver who thinks “if I had slowed down, I wouldn’t have skidded” is likely to drive more carefully next time. The danger is dwelling on it. So if you find yourself beating yourself up about a decision, try comparing downwards for a change. Things could have been a lot worse.</p></div>
<p><b>Question:</b> according to the article, why do bronze medallists often look happier than silver medallists?</p>`,
  audio:'Why silver feels worse than bronze. Every Olympic final ends with three smiling athletes on the podium. Or does it? In the mid-1990s, a team of American psychologists studied television footage of medallists and asked volunteers to rate how happy each athlete looked. The results were surprising: bronze medallists generally looked happier than silver medallists, even though they had performed worse. The explanation lies in what researchers call counterfactual thinking: our habit of imagining how things might have turned out. A silver medallist tends to compare upwards: “If I had started a fraction faster, I would have won gold.” A bronze medallist compares downwards: “If I had been a fraction slower, I wouldn’t have got a medal at all.” Same podium, very different “what ifs”. Researchers noticed another pattern when they asked people about their biggest regrets. In the short term, we tend to regret things we did: the angry email, the expensive purchase. Over a lifetime, however, the balance shifts. Older people are far more likely to regret what they didn’t do: the course they never took, the friend they never called, the job they turned down. Actions can be explained, apologised for and learnt from; inactions stay open, and the mind keeps rewriting them. Psychologists don’t see this as entirely negative. Imagining what might have been helps us learn from our mistakes: a driver who thinks “if I had slowed down, I wouldn’t have skidded” is likely to drive more carefully next time. The danger is dwelling on it. So if you find yourself beating yourself up about a decision, try comparing downwards for a change. Things could have been a lot worse.',
  opts:['Because most of them expected to finish further down.','Because silver medals get less attention on television.','Because they compare themselves with athletes who won no medal at all.','Because they regret things they did, not things they didn’t do.'], ans:2,
  why:'The bronze medallist <i lang="en">compares downwards</i>: <i lang="en">If I had been a fraction slower, I wouldn’t have got a medal at all.</i> The silver medallist compares upwards, with the gold medal he nearly won.'},

 {kind:'Dictée', h:'Dictation: a missed train',
  p:'Listen and write exactly what you hear. You can replay it as often as you like and use “Plus lentement”.',
  dictee:'If we had left ten minutes earlier, we would have caught the last train.',
  why:'Past perfect in the <i lang="en">if</i>-clause (<i lang="en">had left</i>), <i lang="en">would have + caught</i> in the result. <i lang="en">Caught</i> is the past participle of <i lang="en">catch</i>: watch the spelling, <i lang="en">-aught</i>.'},

 {kind:'Oral', h:'From memory: an invitation you missed',
  p:'This time the sentence isn’t written. Listen, then say it from memory. Keep <i lang="en">had</i> and <i lang="en">have</i> light, and stress the verbs that carry the meaning.',
  dire:{t:'If I had known you were in town, I would have come to see you.', cache:true}},

 {kind:'Oral', h:'Speak: a turning point in your life',
  p:`<p>Speak for about one minute. Describe a decision or an event that changed your life (a move, a meeting, a choice of studies, an accident…). Say what happened, how things <b>would have turned out</b> if it hadn’t happened, how your life <b>would be different now</b>, and whether you have any regrets. Tap “Parler”, then “J’ai fini”.</p>`,
  oral:{modele:'When I was eighteen, I almost studied law, because my parents wanted me to. In the end, I chose biology, and looking back on it, that was a real turning point. If I had studied law, I would never have spent a year in Canada, and I wouldn’t have discovered how much I love working outdoors. I probably wouldn’t be working in a national park now. Of course, I sometimes think about what might have been: I would probably earn more if I had become a lawyer. But I have no regrets. If anything, I wish I had travelled even more during my studies.',
   criteres:['I described a real decision or event in the past','I used at least one third conditional (If I had…, I would have…)','I used a mixed conditional about the present (…, I would be… now)','I expressed a regret with I wish, If only or should have','I used at least two expressions from the unit (looking back, a turning point, no regrets…)']}},

 {kind:'Écriture', h:'Write: the road not taken',
  p:'A website collects readers’ stories under the title <i lang="en">“The road not taken”</i>. Write your contribution (about 180 words). Describe a decision you made (or didn’t make), imagine how things would have turned out otherwise, say how your life would be different today, and end with what you have learnt. Real or invented: both are fine.',
  ecrire:{min:180, modele:'Ten years ago, I was offered a place at a music college in London. I was nineteen, I had never lived away from home, and I panicked. I turned the offer down and studied economics in Lyon instead.\n\nIn hindsight, it was a turning point. If I had gone to London, I would have spent three years practising the piano for eight hours a day. I might have become a professional musician, or I might have given up after a year: nobody can tell. What I do know is that my life would be completely different today. I probably wouldn’t be working in a bank, and my English would be much better!\n\nFor a long time, I beat myself up about it. I wish I had been braver, and I should have at least talked to my piano teacher before saying no. But looking back, the decision was also a blessing in disguise: in Lyon, I met the friends who started a band with me, and we still play together every weekend.\n\nWhat I have learnt is simple: when you are afraid, ask for advice before you say no.',
   criteres:[{t:'I used a third conditional (If … had + participle, … would/could/might have + participle)', re:'\\bif\\b[^.]*\\bhad\\b[^.]*\\b(would|could|might|’d|\'d)(n’t|n\'t| not)? have\\b'},{t:'I used would + verb to describe the present (I would be…, I wouldn’t live…)', re:'\\b(would|’d|\'d)(n’t|n\'t| not)? (still |probably |never )?(be|live|work|know|speak|own|earn)\\b'},{t:'I expressed a regret with I wish, If only or should have', re:'\\b(wish|if only|should(n’t|n\'t| not)? have|should’ve|should\'ve)\\b'},'I described the real facts clearly before imagining the alternative','I used expressions such as in hindsight, looking back, a turning point, a blessing in disguise',{t:'I ended with what I have learnt', re:'\\b(learnt|learned|lesson)\\b'}]}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Third conditional</b> (unreal past): <i lang="en">If + had + participle, would/could/might have + participle</i>. <i lang="en">If I had known, I would have come.</i> Never <i lang="en">would</i> after <i lang="en">if</i>.</li><li><b>Mixed conditionals</b>: past condition, present result: <i lang="en">If I had studied medicine, I would be a doctor now.</i> Present condition, past result: <i lang="en">If I weren’t so shy, I would have spoken to her.</i> French works the same way: <i>serais</i> = <i lang="en">would be</i>, <i>serais devenu</i> = <i lang="en">would have become</i>.</li><li>Method: list the facts and their times, reverse each one, pick the forms, then swap clauses if you like.</li><li><b>Regret and criticism</b>: <i lang="en">should (not) have + participle</i>; <i lang="en">I wish / If only + past perfect</i>. Not <i lang="en">I wish I would have</i>, not <i lang="en">should of</i>.</li><li><i lang="en">’d</i> + participle = <i lang="en">had</i>; <i lang="en">’d</i> + <i lang="en">have</i> or verb = <i lang="en">would</i>.</li><li>Pronunciation: <i lang="en">should’ve, would’ve, could’ve</i> = /əv/, stress on the main verb.</li><li>Vocabulary: <i lang="en">turn down an offer, jump at the chance, in hindsight, a turning point, a blessing in disguise, on the spot, dwell on, come to terms with, learn the hard way</i>.</li></ul></div>`},

 {kind:'Mission', h:'Mission: the missed connection',
  p:'Your friend Karim is at the transfer desk at Amsterdam airport. His first flight landed late and he has missed his connection to Toronto. Listen to the conversation, then answer the questions one by one. You can replay it at any time.',
  audio:[['Agent','Good afternoon. How can I help?'],['Karim','Hi. My flight from Geneva landed forty minutes late, and I’ve missed my connection to Toronto.'],['Agent','I’m sorry to hear that. Let me have a look… Yes, the Toronto flight closed its gate at ten past two. If you had landed even fifteen minutes earlier, we would have held the gate for you.'],['Karim','Fifteen minutes! I should have taken the early morning flight, but it was more expensive.'],['Agent','Well, you couldn’t have known about the delay. The good news is that there’s a seat on tomorrow’s flight at ten twenty-five, and since the delay was our fault, we’ll pay for your hotel tonight.'],['Karim','That’s something, I suppose. If I’d known I was going to spend the night here, I would have packed a toothbrush in my hand luggage.'],['Agent','We can give you an overnight kit. And here’s a meal voucher for fifteen euros.'],['Karim','Thanks. I just wish the pilot had warned us about the delay before we boarded in Geneva.']], cache:true,
  parts:[
   {q:'a) According to the agent, what would have happened if Karim’s plane had landed fifteen minutes earlier?', opts:['He would have had to buy a new ticket.','The airline would have held the gate for him.','He would have taken the early morning flight.','He would have got a free hotel room.'], ans:1, hint:'Listen to the agent’s third conditional: <i lang="en">If you had landed…, we would have…</i>', why:'<i lang="en">If you had landed even fifteen minutes earlier, we would have held the gate for you.</i> They would have kept the gate open.'},
   {q:'b) When does Karim’s new flight leave? Write the time in figures (hh:mm).', lab:'Time', txt:['10:25','10.25','1025','10h25'], hint:'<i lang="en">ten twenty-five</i>, tomorrow.', why:'<i lang="en">tomorrow’s flight at ten twenty-five</i>: 10:25.'},
   {q:'c) Karim regrets choosing the cheaper flight. Write his regret with <i lang="en">I wish</i> and <i lang="en">the early morning flight</i>.', lab:'His sentence', txt:A('I wish I had {taken|booked|caught|chosen} the early morning flight.'), hint:'<i lang="en">wish</i> + past perfect: <i lang="en">I wish I had</i> + past participle.', why:'<i lang="en">I wish I had taken the early morning flight.</i> He said the same thing with <i lang="en">should</i>: <i lang="en">I should have taken the early morning flight.</i>'},
   {q:'d) Karim didn’t pack a toothbrush because he didn’t know he would spend the night in Amsterdam. Write a third conditional starting with <i lang="en">If he had known, …</i>', lab:'Your sentence', txt:A('If he had known, he would have {packed|put|taken|brought} a toothbrush{ in his hand luggage|}.'), hint:'Result in the past: <i lang="en">would have</i> + past participle.', why:'<i lang="en">If he had known, he would have packed a toothbrush in his hand luggage.</i> Both halves are unreal: he didn’t know and didn’t pack one.'}],
  sol:'<p lang="en">Karim’s flight from Geneva landed forty minutes late. If he had landed fifteen minutes earlier, the airline would have held the gate. He will fly tomorrow at 10:25, and the airline is paying for his hotel because the delay was its fault.</p><p>Regret: <i lang="en">I wish I had taken the early morning flight</i> (= <i lang="en">I should have taken…</i>). Third conditional: <i lang="en">If he had known, he would have packed a toothbrush.</i> Note also <i lang="en">I wish the pilot had warned us</i> : <i lang="en">wish</i> + past perfect for someone else’s past action.</p>'},

 {kind:'Mission', h:'Mission: a letter to an advice column',
  p:`<p>Max has written to the advice column of a weekend magazine. Read his letter, then answer the questions.</p>
<div class="blk" data-t="Dear Hannah"><p lang="en">Five years ago, I dropped out of medical school in my second year. I was exhausted, my grades were slipping, and a friend offered me a job in his new café. I said yes on the spot. The café is doing well and I’m now the manager, but lately I can’t stop thinking about what might have been. My old classmates are qualifying as doctors this summer. If I had stayed, I would be one of them. I keep telling myself I should have taken a year off instead of quitting altogether. Am I too old to go back at 29? Max, Bristol</p></div>`,
  parts:[
   {q:'a) Why did Max leave medical school?', opts:['He failed his final exams.','His parents could no longer pay the fees.','He was exhausted, and a friend offered him a job.','He had always wanted to open his own café.'], ans:2, hint:'Look at the second sentence of the letter.', why:'<i lang="en">I was exhausted, my grades were slipping, and a friend offered me a job in his new café.</i>'},
   {q:'b) Which sentence from the letter is a mixed conditional (past condition, present result)?', opts:['I said yes on the spot.','If I had stayed, I would be one of them.','I should have taken a year off.','Am I too old to go back at 29?'], ans:1, hint:'Look for <i lang="en">had</i> + participle in one half and <i lang="en">would</i> + infinitive in the other.', why:'<i lang="en">If I had stayed</i> (past perfect: a finished decision), <i lang="en">I would be one of them</i> (would + infinitive: now).'},
   {q:'c) Rewrite Max’s regret <i lang="en">“I should have taken a year off”</i> with <i lang="en">I wish</i>.', lab:'Your sentence', txt:A('I wish I had taken a year off{ instead of quitting altogether| instead of quitting|}.'), hint:'<i lang="en">I wish</i> + past perfect.', why:'<i lang="en">I wish I had taken a year off.</i> The meaning is the same; <i lang="en">wish</i> sounds more personal, <i lang="en">should have</i> more like a judgement.'},
   {q:'d) You are Hannah. Remind Max of the positive side. Start with <i lang="en">If you hadn’t left medical school, you…</i> and say that he would never have become the manager of the café.', lab:'Your sentence', txt:A('If you had not left medical school, you would {never|not} have become {the |}manager of {the|a successful|this|your friend’s} café.','If you had not left medical school, you would {never|not} have become the café’s manager.'), hint:'Past condition, past result: <i lang="en">would never have</i> + past participle of <i lang="en">become</i>.', why:'<i lang="en">If you hadn’t left medical school, you would never have become the manager of the café.</i> <i lang="en">Become</i> has the same form in the infinitive and the past participle.'}],
  sol:'<p>Max left medical school because he was exhausted and was offered a job. His mixed conditional, <i lang="en">If I had stayed, I would be one of them</i>, links a past decision to the present. With <i lang="en">wish</i>: <i lang="en">I wish I had taken a year off.</i> A third conditional shows the other side: <i lang="en">If you hadn’t left medical school, you would never have become the manager of the café.</i></p><p lang="en">Hannah might add: it’s no use crying over spilt milk. At 29, you are not too old to go back, so don’t let the chance slip through your fingers if you really want it.</p>'},
]},

/* ===================== 5. Mysteries ===================== */
{subj:'en', sem:'b2', id:'en-b2-deduction', o:5, h:'Mysteries', p:'Make deductions and speculate about the past with <i lang="en">must have, might have, can’t have</i>, and judge past actions with <i lang="en">could have, should have</i> and <i lang="en">needn’t have</i>.', steps:[
 {kind:'Écoute', h:'Who’s been in the flat?',
  p:`<p>By the end of this unit, you’ll be able to work out what probably happened from clues, say how sure you are, rule explanations out, and comment on what people could or should have done.</p>
<p>Jess and Sam come home after a weekend away and find their flat in a strange state. <b>Listen without reading</b>, then answer. The transcript appears after your answer.</p>
<p><b>Question:</b> who do they conclude came into the flat?</p>`,
  audio:[['Jess','Sam, come and look at this. The kitchen window’s wide open.'],['Sam','That’s weird. I’m sure I closed it before we left. Someone must have opened it from outside.'],['Jess','And look at the floor: muddy footprints everywhere. Tiny ones.'],['Sam','Do you think we’ve been burgled?'],['Jess','It can’t have been a burglar. My laptop’s still on the table, and so is your wallet.'],['Sam','Fair point. Hang on, where’s Biscuit? She isn’t in her basket.'],['Jess','She might have got out through the window. Or someone might have let her out.'],['Sam','And who’s eaten half of my birthday cake?'],['Jess','Well, it can’t have been Biscuit. Cats don’t eat chocolate cake.'],['Sam','Small footprints, cake, an open window… It must have been a child.'],['Jess','Oh no. Mrs Patel’s grandson is staying with her this week. He must have climbed over the garden wall. He’s been dying to play with Biscuit.'],['Sam','He needn’t have climbed in, though. He could have just knocked on the door.'],['Jess','We weren’t here to answer, remember? Oh, listen. There’s someone at the door.'],['Sam','That’ll be him. And I bet he’s got Biscuit with him.']], cache:true,
  opts:['A burglar who was disturbed before he could take anything.','Sam’s brother, who has a key.','Their neighbour’s young grandson.','Mrs Patel herself, looking for her cat.'], ans:2,
  why:'Small footprints and a half-eaten cake: <i lang="en">It must have been a child.</i> Jess concludes that <i lang="en">Mrs Patel’s grandson must have climbed over the garden wall</i>. A burglar is ruled out: <i lang="en">It can’t have been a burglar</i>, since nothing was taken.'},

 {kind:'Vocabulaire', h:'Clues and conclusions',
  p:`<p>The language of investigation is useful far beyond detective stories: at work, in the news, or when your flatmate swears he didn’t eat your cake. Tap a line to hear it, then say it aloud.</p>`,
  mots:[['a clue','un indice','The police found an important clue in the garden.'],['evidence','des preuves (indénombrable)','There isn’t enough evidence to arrest him.'],['a witness','un témoin','A witness saw a man running away.'],['a suspect','un suspect','The main suspect has an alibi.'],['an alibi','un alibi','She has a perfect alibi: she was on a plane.'],['to rule something out','écarter, exclure','We can rule out a burglary: nothing was taken.'],['to jump to conclusions','tirer des conclusions hâtives','Don’t jump to conclusions: maybe he just forgot.'],['to put two and two together','faire le rapprochement','I saw the ring and put two and two together.'],['to get to the bottom of something','tirer quelque chose au clair','I’m determined to get to the bottom of this.'],['to draw a conclusion','tirer une conclusion','It’s too early to draw any conclusions.'],['a plausible explanation','une explication plausible','There must be a plausible explanation.'],['a far-fetched theory','une théorie tirée par les cheveux','That theory sounds a bit far-fetched.'],['it doesn’t add up','ça ne tient pas debout','His story doesn’t add up.'],['to vanish into thin air','disparaître sans laisser de trace','The money seems to have vanished into thin air.'],['a dead giveaway','un indice qui trahit tout','The chocolate on his face was a dead giveaway.']],
  note:'<b>Attention :</b> <i lang="en">evidence</i> est indénombrable : <i lang="en">a piece of evidence</i>, <i lang="en">some evidence</i>, jamais « an evidence » ni « evidences ». Et ce mot n’a rien à voir avec « une évidence » (= <i lang="en">something obvious</i>). « C’est évident » se dit <i lang="en">It’s obvious</i>.'},

 {kind:'Pratique', h:'Recall: don’t jump to conclusions',
  p:'Your friend is sure his neighbour stole his parcel. Calm him down. <b>Question:</b> how do you say « Ne tire pas de conclusions hâtives : il n’y a aucune preuve. » ?', lab:'Your sentence',
  txt:A('Do not jump to conclusions, there is {no|not any} evidence{ at all|}.','Do not jump to conclusions, we do not have any evidence.','Do not jump to conclusions, you do not have any evidence.','Do not jump to conclusions, you have no evidence.'),
  why:'<i lang="en">Don’t jump to conclusions: there’s no evidence.</i> <i lang="en">Evidence</i> is uncountable: <i lang="en">no evidence</i>, <i lang="en">any evidence</i>, never « evidences ».'},

 {kind:'Grammaire', h:'Deductions about the past: must have, can’t have, might have',
  p:`<p>Sam says: <i lang="en">Someone <b>must have opened</b> the window.</i> Jess answers: <i lang="en">It <b>can’t have been</b> a burglar.</i> Neither of them saw what happened: they are <b>deducing</b> it from clues. You already do this about the present (<i lang="en">He must be tired. She can’t be serious.</i>). For the past, add <b>have + past participle</b>.</p>
<div class="def"><ul><li><b>must have + participle</b>: I’m almost sure it happened. <i lang="en">The streets are wet: it must have rained.</i></li><li><b>might / may / could have + participle</b>: perhaps it happened. <i lang="en">She might have missed the bus.</i></li><li><b>might not / may not have + participle</b>: perhaps it didn’t happen. <i lang="en">He may not have seen your message.</i></li><li><b>can’t / couldn’t have + participle</b>: I’m almost sure it didn’t happen. <i lang="en">It can’t have been the cat.</i></li></ul></div>
<div class="idea"><p>Picture a scale of certainty: <i lang="en">must have</i> (about 95% yes) → <i lang="en">might / may / could have</i> (50%) → <i lang="en">can’t / couldn’t have</i> (about 95% no). The modal shows how sure you are; <i lang="en">have + participle</i> puts the event in the past. For an action in progress, use <b>have been + -ing</b>: <i lang="en">His eyes were red: he must have been crying.</i> For a passive: <i lang="en">The window must have been forced.</i></p></div>
<div class="warn"><p><b>Pièges :</b> le contraire de <i lang="en">must have</i> n’est pas <i lang="en">mustn’t have</i> mais <b>can’t have</b>. Et « il a dû » est ambigu en français : « Il a dû partir tôt, il avait un train » = obligation → <i lang="en">He <b>had to</b> leave early</i> ; « Il a dû partir, la lumière est éteinte » = déduction → <i lang="en">He <b>must have</b> left</i>. De même, « il a pu se tromper » = <i lang="en">he may / might have made a mistake</i>, pas « he could make a mistake ».</p></div>`,
  audio:'The streets are wet: it must have rained. She might have missed the bus. It can’t have been the cat. His eyes were red: he must have been crying.'},

 {kind:'Méthode', h:'Choosing the right modal for a deduction',
  p:`<p><b>When:</b> you have clues about something that happened and want to say what you think. <b>Why it works:</b> English separates two pieces of information that French mixes in « a dû » or « a pu »: <b>how sure</b> you are (the modal) and <b>when</b> it happened (<i lang="en">have + participle</i> for the past). <b>How:</b></p>
<ul><li>Is it about now or the past? Past → modal + <i lang="en">have + participle</i>.</li><li>How sure are you? Sure it happened → <i lang="en">must</i>; perhaps → <i lang="en">might / may / could</i>; sure it didn’t → <i lang="en">can’t / couldn’t</i>.</li><li>Was the action finished or in progress? In progress → <i lang="en">have been + -ing</i>.</li></ul>`,
  demo:{enonce:'Clues: <i lang="en">Your colleague Nina arrived at work this morning soaking wet, without an umbrella. Her bike wasn’t in the bike rack. All morning she looked exhausted and kept yawning.</i> Make four deductions.',
   etapes:[{f:'Sure it happened: <i lang="en">She must have got caught in the rain.</i>',w:'She’s soaking wet, so you’re almost sure. Past, finished → <i lang="en">must have + participle</i>.'},
    {f:'Sure it didn’t: <i lang="en">She can’t have come by car, or she’d be dry.</i>',w:'Almost sure it didn’t happen → <i lang="en">can’t have</i>, not <i lang="en">mustn’t have</i>.'},
    {f:'Possible: <i lang="en">She might have walked, or she may have taken the bus.</i>',w:'No bike, no car: two explanations and no proof → <i lang="en">might / may have</i>.'},
    {f:'In progress: <i lang="en">She must have been working late last night.</i>',w:'Yawning suggests a long activity → <i lang="en">must have been + -ing</i>. Less sure: <i lang="en">She might have been out with friends.</i>'}],
   conclusion:'<i lang="en">She must have got caught in the rain. She can’t have come by car. She might have walked. She must have been working late.</i>'}},

 {kind:'Pratique', h:'Your turn: must have',
  p:'Clues: <i lang="en">The lights are off, the curtains are closed and nobody answers the door.</i> You’re almost sure your friends aren’t at home. <b>Question:</b> write a deduction with <i lang="en">must</i>, starting with <i lang="en">They…</i>', lab:'Your sentence',
  txt:A('They must have {gone out|left|gone away|already gone out|already left|gone to bed}{ already|}.'),
  why:'Almost sure + past → <i lang="en">They must have gone out</i> (or <i lang="en">left</i>). <i lang="en">must have + participle</i>.'},

 {kind:'Pratique', h:'Your turn: can’t have',
  p:'A colleague says: <i lang="en">Mark saw the email about the meeting.</i> But you know Mark was on a long flight with no internet all day. <b>Question:</b> contradict her with a deduction, starting with <i lang="en">He…</i>', lab:'Your sentence',
  txt:A('He {cannot|could not} have {seen|read} {the email|the email about the meeting|it}.'),
  why:'Almost sure it didn’t happen → <i lang="en">He can’t have seen the email</i> (or <i lang="en">couldn’t have</i>). <i lang="en">He mustn’t have seen it</i> is wrong for a deduction.'},

 {kind:'Pratique', h:'Your turn: perhaps',
  p:'Translate into English with a modal verb. The speaker isn’t sure. <b>Question:</b> how do you say « Elle a peut-être raté son train. » ?', lab:'Your sentence',
  txt:A('She {might|may|could} have missed {her|the} train.'),
  why:'« peut-être » about the past → <i lang="en">might / may / could have + participle</i>: <i lang="en">She might have missed her train.</i> Not « she could miss », which is about the future.'},

 {kind:'Pratique', h:'Your turn: an action in progress',
  p:'Clues: <i lang="en">When I called Leo at midnight, he answered at once, there was loud music behind him and people were laughing.</i> <b>Question:</b> what was he doing? Write a deduction with <i lang="en">must have been</i>, starting with <i lang="en">He…</i>', lab:'Your sentence',
  txt:A('He must have been {partying|at a party|having a party|throwing a party|celebrating|out with friends|at a club}.'),
  why:'An activity in progress at that moment → <i lang="en">must have been + -ing</i>: <i lang="en">He must have been partying</i> (or simply <i lang="en">He must have been at a party</i>).'},

 {kind:'Grammaire', h:'Judging the past: could have, should have, needn’t have',
  p:`<p>Some past modals don’t deduce anything: they <b>judge</b> what happened. Sam says: <i lang="en">He <b>needn’t have climbed</b> in. He <b>could have</b> just <b>knocked</b>.</i> Both facts are known; Sam is commenting on them.</p>
<div class="def"><ul><li><b>could have + participle</b>: a possibility that existed but wasn’t used. <i lang="en">You could have been killed!</i> Often a reproach: <i lang="en">You could have told me!</i></li><li><b>should have / shouldn’t have + participle</b>: the right or wrong thing to do (previous unit), and also an <b>expectation</b>: <i lang="en">The parcel should have arrived by now.</i></li><li><b>needn’t have + participle</b>: you did it, but it wasn’t necessary. <i lang="en">You needn’t have brought wine: we’ve got plenty.</i></li><li><b>didn’t need to + infinitive</b>: it wasn’t necessary, and usually you didn’t do it. <i lang="en">I didn’t need to take a taxi: Sara gave me a lift.</i></li></ul></div>
<div class="idea"><p>The difference between <i lang="en">needn’t have done</i> and <i lang="en">didn’t need to do</i> lies in what really happened. With <i lang="en">needn’t have</i>, the action took place: wasted effort. With <i lang="en">didn’t need to</i>, we usually understand it didn’t (though the context can say otherwise).</p></div>
<div class="warn"><p><b>Pour les francophones :</b> « Tu aurais pu me prévenir ! » = <i lang="en">You could have warned me!</i> ; « Tu n’aurais pas dû venir » = <i lang="en">You shouldn’t have come</i> ; « Ce n’était pas la peine d’apporter un cadeau » (mais tu l’as fait) = <i lang="en">You needn’t have brought a present</i>. Attention : <i lang="en">could have</i> ne veut jamais dire « a pu » au sens d’une réussite : « j’ai pu finir à temps » = <i lang="en">I managed to finish</i> ou <i lang="en">I was able to finish</i> on time.</p></div>`,
  audio:'You could have told me! The parcel should have arrived by now. You needn’t have brought wine. I didn’t need to take a taxi.'},

 {kind:'Méthode', h:'Translating « a dû », « aurait dû », « a pu », « aurait pu »',
  p:`<p><b>When:</b> you think in French and need one of these four little phrases. <b>Why it works:</b> French uses <i>devoir</i> and <i>pouvoir</i> for very different meanings, while English has a separate structure for each meaning. So decide the <b>meaning</b> first, then pick the form. <b>How:</b></p>
<ul><li>« a dû »: obligation → <i lang="en">had to</i>; deduction → <i lang="en">must have</i>.</li><li>« aurait dû »: the right thing, or an expectation → <i lang="en">should have</i>.</li><li>« a pu »: managed to → <i lang="en">was able to / managed to</i>; perhaps → <i lang="en">may / might have</i>.</li><li>« aurait pu »: a possibility not used, or a reproach → <i lang="en">could have</i>.</li></ul>`,
  demo:{enonce:'Translate: 1) « Il a dû attendre deux heures à l’aéroport. » 2) « Il a dû oublier : il n’est pas venu. » 3) « Elle a pu trouver une place assise, finalement. » 4) « Vous auriez pu appeler ! »',
   etapes:[{f:'1) <i lang="en">He had to wait two hours at the airport.</i>',w:'Obligation: he had no choice, and we know it happened → <i lang="en">had to</i>.'},
    {f:'2) <i lang="en">He must have forgotten: he didn’t come.</i>',w:'A deduction from a clue (he didn’t come) → <i lang="en">must have + participle</i>.'},
    {f:'3) <i lang="en">She managed to find a seat in the end.</i>',w:'A real success in the past → <i lang="en">managed to</i> or <i lang="en">was able to</i>, never <i lang="en">could have</i>.'},
    {f:'4) <i lang="en">You could have called!</i>',w:'A possibility that wasn’t used, with a reproach → <i lang="en">could have + participle</i>.'}],
   conclusion:'Same French verbs, four different English structures: always ask yourself what the sentence <b>means</b> before translating.'}},

 {kind:'Pratique', h:'Your turn: « il a dû »',
  p:'Context: Paul isn’t answering his phone, his car has gone and his suitcase isn’t in the hall. <b>Question:</b> how do you say « Il a dû partir en vacances. » ?', lab:'Your sentence',
  txt:A('He must have {gone|left|gone away} on {holiday|vacation}.'),
  why:'A deduction from clues → <i lang="en">He must have gone on holiday.</i> <i lang="en">He had to go on holiday</i> would mean somebody forced him to. (<i lang="en">vacation</i> is American.)'},

 {kind:'Pratique', h:'Your turn: needn’t have',
  p:'You carried an umbrella around all day, but it didn’t rain. <b>Question:</b> comment on it with <i lang="en">needn’t have</i>, starting with <i lang="en">I…</i>', lab:'Your sentence',
  txt:A('I need not have {taken|brought|carried} {an|my|the} umbrella{ with me|}.','I need not have {taken|brought|carried} it{ with me|}.'),
  why:'You did take it, and it was unnecessary → <i lang="en">I needn’t have taken an umbrella.</i> <i lang="en">I didn’t need to take an umbrella</i> would suggest you left it at home.'},

 {kind:'Pratique', h:'Put the reproach in order',
  p:'Tap the words in the right order. <b>Question:</b> what does a worried parent say to a teenager who came home at three in the morning without calling?',
  ordre:['You','could','at','least','have','sent','me','a','message!'],
  alt:['You could have at least sent me a message'],
  why:'<i lang="en">You could at least have sent me a message!</i> <i lang="en">could have + participle</i> = a possibility that wasn’t used, here as a reproach. <i lang="en">At least</i> can also come after <i lang="en">have</i>.'},

 {kind:'Prononciation', h:'Weak forms: must’ve, can’t’ve, and the British can’t',
  p:`<p>As in the previous unit, <i lang="en">have</i> after a modal shrinks to /əv/: <i lang="en">must have</i> /ˈmʌstəv/, <i lang="en">might have</i> /ˈmaɪtəv/, <i lang="en">can’t have</i> /ˈkɑːntəv/. The modal and the participle carry the stress: <i lang="en">She <b>must</b> have <b>missed</b> it.</i></p>
<div class="idea"><p>In British English, <i lang="en">can</i> and <i lang="en">can’t</i> differ mainly in their vowel: <i lang="en">can</i> is usually weak, /kən/, while <i lang="en">can’t</i> has a long, open vowel, /kɑːnt/, and is stressed. The final <i lang="en">t</i> is often barely audible, so listen for the vowel. In American English, <i lang="en">can’t</i> rhymes with <i lang="en">ant</i>, /kænt/.</p></div>
<div class="warn"><p><b>Pour les francophones :</b> dans <i lang="en">must have</i>, le <i lang="en">t</i> se lie au /əv/ : à peu près « meus-tev ». Ne sépare pas les trois mots, et n’aspire pas le <i lang="en">h</i> de <i lang="en">have</i> ici.</p></div>
<p>Listen, then say the sentences aloud.</p>`,
  dire:'She must have missed the train. It can’t have been him.'},

 {kind:'Vocabulaire', h:'Speculating and hedging',
  p:`<p>Modals aren’t the only way to speculate. These phrases help you sound natural, and show exactly how sure you are.</p>`,
  mots:[['I bet…','je parie que, à tous les coups','I bet he forgot again.'],['There’s no way…','il est impossible que','There’s no way she walked all that way.'],['Chances are…','il y a de fortes chances que','Chances are they’ve already left.'],['My guess is that…','à mon avis, je suppose que','My guess is that the battery died.'],['presumably','vraisemblablement, sans doute','Presumably the train was cancelled.'],['apparently','apparemment, il paraît que','Apparently, nobody saw anything.'],['It’s highly unlikely that…','il est très peu probable que','It’s highly unlikely that anyone noticed.'],['to give someone the benefit of the doubt','accorder le bénéfice du doute','Let’s give him the benefit of the doubt.']],
  note:'<b>Faux ami :</b> <i lang="en">eventually</i> = finalement ; « éventuellement » = <i lang="en">possibly</i>, <i lang="en">perhaps</i>. Et <i lang="en">apparently</i> signale une information rapportée (« il paraît que »), pas une évidence.'},

 {kind:'Lecture', h:'Reading: the ship that sailed on alone',
  p:`<p>Read this article about one of the most famous mysteries of the sea, then answer. You can also listen to it.</p>
<div class="blk" data-t="The ship that sailed on alone"><p lang="en">On 4 December 1872, the crew of the Dei Gratia spotted a ship drifting between the Azores and the coast of Portugal. It was the Mary Celeste, an American merchant ship that had left New York a month earlier, bound for Genoa. When the sailors climbed aboard, they found nobody. The captain, Benjamin Briggs, his wife, their two-year-old daughter and the seven crew members had vanished into thin air.</p>
<p lang="en">The ship itself was in reasonable condition. There was water below deck, but there were six months’ worth of food and drinking water on board, and the sailors’ belongings had not been touched. The cargo, around 1,700 barrels of industrial alcohol, was almost intact. Only one thing was obviously missing: the lifeboat.</p>
<p lang="en">So what happened? The ship can’t have been attacked by pirates: they would surely have taken the cargo and the valuables. A mutiny seems equally unlikely, since no sign of a struggle was found. Most historians agree that the people on board must have left in the lifeboat, and in a hurry. But why would an experienced captain abandon a ship that was still seaworthy?</p>
<p lang="en">Several theories have been put forward. Nine of the barrels turned out to be empty when the cargo was unloaded in Genoa, so alcohol fumes might have built up in the hold, making Briggs fear an explosion. Alternatively, a faulty pump may have convinced him that the ship was sinking faster than it really was. Either way, the lifeboat was never seen again: it may have been caught in a storm, or simply drifted until the people on board died.</p>
<p lang="en">Writers have added to the mystery ever since. In 1884, a young Arthur Conan Doyle published a story about the ship, inventing details that many readers took as fact. We will probably never know exactly what happened: the only people who could have told us were in that lifeboat.</p></div>
<p><b>Question:</b> according to the article, why do historians reject the pirate theory?</p>`,
  audio:'The ship that sailed on alone. On 4 December 1872, the crew of the Dei Gratia spotted a ship drifting between the Azores and the coast of Portugal. It was the Mary Celeste, an American merchant ship that had left New York a month earlier, bound for Genoa. When the sailors climbed aboard, they found nobody. The captain, Benjamin Briggs, his wife, their two-year-old daughter and the seven crew members had vanished into thin air. The ship itself was in reasonable condition. There was water below deck, but there were six months’ worth of food and drinking water on board, and the sailors’ belongings had not been touched. The cargo, around 1,700 barrels of industrial alcohol, was almost intact. Only one thing was obviously missing: the lifeboat. So what happened? The ship can’t have been attacked by pirates: they would surely have taken the cargo and the valuables. A mutiny seems equally unlikely, since no sign of a struggle was found. Most historians agree that the people on board must have left in the lifeboat, and in a hurry. But why would an experienced captain abandon a ship that was still seaworthy? Several theories have been put forward. Nine of the barrels turned out to be empty when the cargo was unloaded in Genoa, so alcohol fumes might have built up in the hold, making Briggs fear an explosion. Alternatively, a faulty pump may have convinced him that the ship was sinking faster than it really was. Either way, the lifeboat was never seen again: it may have been caught in a storm, or simply drifted until the people on board died. Writers have added to the mystery ever since. In 1884, a young Arthur Conan Doyle published a story about the ship, inventing details that many readers took as fact. We will probably never know exactly what happened: the only people who could have told us were in that lifeboat.',
  opts:['Because no pirates operated near the Azores at that time.','Because the cargo and the sailors’ belongings were left on board.','Because the captain was known to be a fair man.','Because the lifeboat was still tied to the ship.'], ans:1,
  why:'<i lang="en">The ship can’t have been attacked by pirates: they would surely have taken the cargo and the valuables.</i> The belongings <i lang="en">had not been touched</i> and the cargo was <i lang="en">almost intact</i>.'},

 {kind:'Dictée', h:'Dictation: the open gate',
  p:'Listen and write exactly what you hear. You can replay it and use “Plus lentement”.',
  dictee:'Someone must have left the gate open, because the dog has disappeared again.',
  why:'<i lang="en">must have left</i>: a deduction about the past. Don’t confuse <i lang="en">left</i> (participle of <i lang="en">leave</i>) with <i lang="en">lift</i>, and watch the double <i lang="en">s</i> and single <i lang="en">p</i> in <i lang="en">disappeared</i>.'},

 {kind:'Oral', h:'From memory: ruling it out',
  p:'The sentence isn’t written this time. Listen, then say it from memory. Make the long British vowel in <i lang="en">can’t</i> clearly audible.',
  dire:{t:'It can’t have been a burglar: nothing was taken.', cache:true}},

 {kind:'Oral', h:'Speak: the empty desk',
  p:`<p>Speak for about one minute. Situation: your colleague Daniel, who is never late, didn’t come to work today. His phone is switched off and his desk has been cleared: even his plant has gone. But his coffee mug is still in the kitchen. Speculate about what happened, rule some explanations out, and say what he could or should have done.</p>`,
  oral:{modele:'Well, Daniel must have planned this, because his desk has been completely cleared. He can’t have been ill: you don’t take your plant home when you’ve got the flu. He might have found another job, or he may have been moved to another office. My guess is that he resigned last week and didn’t want to tell anyone. He can’t have left in a hurry, or he wouldn’t have had time to tidy up. The mug is strange: he might simply have forgotten it. Either way, he could have said goodbye! He should at least have sent an email to the team.',
   criteres:['I made at least one confident deduction with must have','I ruled something out with can’t have or couldn’t have','I offered possibilities with might have, may have or could have','I judged his behaviour with could have or should have','I used a hedging phrase (My guess is…, I bet…, Chances are…)']}},

 {kind:'Écriture', h:'Write: a strange night in the neighbourhood',
  p:'Something odd happened in your street last night. Choose a situation or invent your own: a car was found with its doors open and the engine running; a light was seen in a house that has been empty for years; all the garden gnomes in the street have been moved. Write a post for your neighbourhood online group (about 180 words). Describe the clues, suggest explanations, rule some out, and ask your neighbours for information.',
  ecrire:{min:180, modele:'Hi everyone,\n\nHas anyone else noticed the blue car outside number 14 on Elm Road? When I walked past at seven this morning, the doors were open, the engine was running and the radio was on, but there was nobody inside or nearby.\n\nThe driver must have left in a hurry, because a handbag and a phone are still lying on the passenger seat. It can’t have been stolen: a thief wouldn’t have left a phone behind, and there’s no sign of a break-in. My guess is that it might have been a medical emergency. The owner may have run into one of the houses to help someone, or an ambulance might have taken them to hospital. There’s also a far-fetched theory going around that it’s linked to the film crew who were here last week, but I wouldn’t jump to conclusions.\n\nWhatever happened, the owner could have at least switched off the engine! I’ve called the police on the non-emergency number, so they should have arrived by the time you read this.\n\nIf you saw or heard anything last night, please send me a message.\n\nThanks,\nClaire',
   criteres:[{t:'I made a confident deduction with must have', re:'\\bmust( have|’ve|\'ve)\\b'},{t:'I ruled something out with can’t have or couldn’t have', re:'\\b(can’t|can\'t|cannot|couldn’t|couldn\'t|could not)( have|’ve|\'ve)\\b'},{t:'I suggested possibilities with might have, may have or could have', re:'\\b(might|may|could)( not)?( have|’ve|\'ve)\\b'},'I described the clues before speculating','I used a hedging phrase or an expression from the unit (my guess is, presumably, jump to conclusions…)',{t:'I asked my neighbours for information', re:'\\?|\\bplease\\b'}]}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Deductions about the past</b>: modal + <i lang="en">have + participle</i>. <i lang="en">must have</i> (almost sure yes), <i lang="en">might / may / could have</i> (perhaps), <i lang="en">might not / may not have</i> (perhaps not), <i lang="en">can’t / couldn’t have</i> (almost sure no). Never <i lang="en">mustn’t have</i> for a deduction.</li><li>Action in progress: <i lang="en">must have been + -ing</i>; passive: <i lang="en">must have been + participle</i>.</li><li><b>Judging the past</b>: <i lang="en">could have</i> (possibility not used, reproach), <i lang="en">should have</i> (right thing, expectation), <i lang="en">needn’t have done</i> (done, but unnecessary) ≠ <i lang="en">didn’t need to do</i> (usually not done).</li><li>Translating: « a dû » = <i lang="en">had to</i> (obligation) or <i lang="en">must have</i> (deduction); « aurait dû » = <i lang="en">should have</i>; « a pu » = <i lang="en">managed to</i> or <i lang="en">may have</i>; « aurait pu » = <i lang="en">could have</i>.</li><li>Pronunciation: <i lang="en">must’ve, might’ve, can’t’ve</i> = /əv/; British <i lang="en">can’t</i> /kɑːnt/ vs weak <i lang="en">can</i> /kən/.</li><li>Vocabulary: <i lang="en">a clue, evidence</i> (uncountable), <i lang="en">rule out, jump to conclusions, put two and two together, it doesn’t add up, far-fetched, I bet, chances are, presumably</i>.</li></ul></div>`},

 {kind:'Mission', h:'Mission: the lost rucksack',
  p:'This morning, Helen left her rucksack on a train. She calls the railway’s lost property office. Listen to the conversation, then answer the questions one by one. You can replay it at any time.',
  audio:[['Clerk','Lost property, how can I help?'],['Helen','Hello. I left a black rucksack on the 8.15 from Brighton to London this morning. I must have put it on the luggage rack and forgotten about it.'],['Clerk','Let me check. We’ve had three black rucksacks handed in today. Was there anything special about yours?'],['Helen','It’s got a red keyring shaped like a fox, and there’s a laptop inside.'],['Clerk','Hmm. One of them has a keyring, but it’s a blue cat. That can’t be yours, then. And the other two were found on trains from Oxford.'],['Helen','Oh no. Someone might have taken it.'],['Clerk','Possibly, or it may still be on the train. That train went on to Bedford, and the cleaners there haven’t sent us anything yet. Sometimes things take a day or two to reach us.'],['Helen','I should have kept it on my lap. And I needn’t have brought the laptop at all: I didn’t even use it.'],['Clerk','Leave me your number, and we’ll call you as soon as anything turns up.']], cache:true,
  parts:[
   {q:'a) Why can’t the rucksack with the keyring be Helen’s?', opts:['It was found on a train from Oxford.','Its keyring is a blue cat, not a red fox.','There’s no laptop inside.','It was handed in yesterday.'], ans:1, hint:'Compare Helen’s description with the clerk’s answer about the keyring.', why:'Helen’s keyring is <i lang="en">a red fox</i>; the clerk’s is <i lang="en">a blue cat</i>: <i lang="en">That can’t be yours, then.</i>'},
   {q:'b) According to the clerk, where might Helen’s rucksack be now?', opts:['At the lost property office in Brighton.','In a police station in Oxford.','Still on the train, unless someone has taken it.','In the cleaners’ office in London.'], ans:2, hint:'Listen to <i lang="en">Possibly, or it may still be…</i>', why:'Helen fears <i lang="en">someone might have taken it</i>; the clerk adds <i lang="en">or it may still be on the train</i>, which went on to Bedford.'},
   {q:'c) Helen is almost sure she put the bag on the luggage rack. Translate her sentence: « J’ai dû le mettre dans le porte-bagages. »', lab:'Her sentence', txt:A('I must have put it {on|in} the luggage rack.','I must have left it {on|in} the luggage rack.'), hint:'It’s a deduction, not an obligation.', why:'Deduction about the past → <i lang="en">I must have put it on the luggage rack.</i> « J’ai dû » here doesn’t mean <i lang="en">I had to</i>.'},
   {q:'d) Helen brought her laptop, but she didn’t use it. Write her comment with <i lang="en">needn’t have</i>, starting with <i lang="en">I…</i>', lab:'Her sentence', txt:A('I need not have brought {the|my} laptop{ at all|}.','I need not have brought it{ at all|}.','I need not have taken {the|my} laptop{ at all|}.'), hint:'<i lang="en">needn’t have</i> + past participle of <i lang="en">bring</i>.', why:'She did bring it, and it was unnecessary: <i lang="en">I needn’t have brought the laptop.</i>'}],
  sol:'<p lang="en">Helen left her rucksack on the 8.15 from Brighton. Of the three rucksacks handed in, one has a blue cat keyring (so it can’t be hers) and two were found on trains from Oxford. Her bag may still be on the train, which went on to Bedford, or someone might have taken it.</p><p>Deduction: <i lang="en">I must have put it on the luggage rack.</i> Unnecessary action that happened: <i lang="en">I needn’t have brought the laptop.</i> Regret: <i lang="en">I should have kept it on my lap.</i></p>'},

 {kind:'Mission', h:'Mission: the missing manuscript',
  p:`<p>A crime writer, Ruth Ellison, kept the only copy of her new novel in a locked drawer in her study. Read her notes about the evening it disappeared, then work out what happened.</p>
<div class="blk" data-t="Saturday evening"><p lang="en">I checked the drawer at 8 p.m.: it was locked, and the manuscript was inside. At 9 p.m., the drawer was open and the manuscript had gone. The lock wasn’t damaged. There are two keys: mine, which hangs on a hook in the hall, and Grace’s. Three people were in the house that evening. Grace, my assistant, left at 6.15, and her train ticket shows she was in Oxford by 7.30. Mr Hale, the gardener, was in the kitchen from 7 to 10: the cook was with him the whole time. My nephew Oliver says he spent the whole evening working in the garden. But it rained heavily from 8 to 9, and when I saw him at 9.15, his clothes were completely dry.</p></div>`,
  parts:[
   {q:'a) Who can’t have taken the manuscript, because someone was with him all evening?', opts:['Oliver','Grace','Mr Hale','The cook'], ans:2, hint:'Find the person who has a witness.', why:'<i lang="en">Mr Hale was in the kitchen from 7 to 10: the cook was with him the whole time.</i> He has an alibi.'},
   {q:'b) Why can’t Grace have opened the drawer herself?', opts:['Because she doesn’t have a key.','Because she was already in Oxford when it was opened.','Because Ruth’s key was hanging in the hall.','Because the lock was damaged.'], ans:1, hint:'Compare the time the drawer was still locked with Grace’s timetable.', why:'The drawer was still locked at 8 p.m., and Grace was in Oxford by 7.30, so she <i lang="en">can’t have opened it herself</i>.'},
   {q:'c) Oliver’s clothes were dry. Write a deduction starting with <i lang="en">Oliver…</i>, using <i lang="en">can’t have</i> and <i lang="en">in the garden</i>.', lab:'Your sentence', txt:A('Oliver {cannot|could not} have been {working |}in the garden {all evening|the whole evening|from 8 to 9|between 8 and 9|when it was raining|}.','Oliver {cannot|could not} have spent the {whole |}evening in the garden.'), hint:'Almost sure it didn’t happen: <i lang="en">can’t have + been</i>.', why:'If he had been in the garden from 8 to 9, he would have got wet: <i lang="en">Oliver can’t have been in the garden all evening.</i>'},
   {q:'d) Now explain how the drawer was opened without damage. Start with <i lang="en">He must have…</i> and use <i lang="en">Ruth’s key</i>.', lab:'Your sentence', txt:A('He must have {used|taken} Ruth’s key{ from the hook| from the hall| to open the drawer| to open it|}.','He must have opened {the drawer|it} with Ruth’s key.'), hint:'The lock wasn’t damaged, and one key was hanging in the hall.', why:'<i lang="en">He must have taken Ruth’s key from the hook in the hall.</i> Grace’s key was in Oxford with her, and the lock wasn’t forced.'},
   {q:'e) Ruth regrets leaving her key in the hall. Translate: « J’aurais dû garder la clé sur moi. »', lab:'Her sentence', txt:A('I should have kept {the|my} key {on me|with me}.','I ought to have kept {the|my} key {on me|with me}.'), hint:'« aurais dû » → <i lang="en">should have</i> + participle.', why:'<i lang="en">I should have kept the key on me.</i> A regret about the past: <i lang="en">should have + participle</i>.'}],
  sol:'<p lang="en">Grace can’t have opened the drawer: she was in Oxford by 7.30, and the drawer was still locked at 8. Mr Hale can’t have done it either: the cook was with him the whole time. Oliver’s story doesn’t add up: it rained from 8 to 9, yet his clothes were dry, so he can’t have been in the garden. He must have taken Ruth’s key from the hook in the hall and opened the drawer between 8 and 9.</p><p>Ruth’s regret: <i lang="en">I should have kept the key on me.</i></p>'},
]},

/* ===================== 6. Getting things done ===================== */
{subj:'en', sem:'b2', id:'en-b2-passive', o:6, h:'Getting things done', p:'Use the passive in every tense, talk about services with <i lang="en">have</i> and <i lang="en">get something done</i>, and report beliefs and rumours with <i lang="en">It is said that…</i> and <i lang="en">He is thought to…</i>', steps:[
 {kind:'Écoute', h:'The house on Mill Lane',
  p:`<p>By the end of this unit, you’ll be able to describe work that is being done, has been done or should have been done, talk about the services you pay for, and report what people say or believe without naming them.</p>
<p>Priya has bought an old house in a village and is showing her friend Dan round. <b>Listen without reading</b>, then answer. The transcript appears after your answer.</p>
<p><b>Question:</b> who is doing most of the work on Priya’s house?</p>`,
  audio:[['Dan','Wow, Priya. It looks like a building site in here!'],['Priya','I know. The kitchen is being completely redone, and the old windows are being replaced next week.'],['Dan','Are you doing all this yourself?'],['Priya','Me? No way. I’m having almost everything done by professionals. I tried to put up a shelf last month and it fell down the next day.'],['Dan','What about the roof? It looked a bit dodgy last time I came.'],['Priya','It’s already been fixed. I had it inspected in March and they found a dozen broken tiles. Apparently, it should have been repaired years ago.'],['Dan','And the garden? There used to be a huge tree there.'],['Priya','I had to get it cut down. Its roots were damaging the foundations.'],['Dan','Shame. So, is it true what people say about this house?'],['Priya','That it’s haunted? Well, it’s said to be the oldest house in the village. It’s thought to have been built around 1750, and a famous poet is believed to have lived here for a while.'],['Dan','A poet, not a ghost, then.'],['Priya','So far. Oh, and don’t leave your bike outside. I had mine stolen from the front garden on my first night.']], cache:true,
  opts:['Priya herself, with some help from Dan.','Professionals she is paying.','Her neighbours, for free.','Nobody yet: the work starts next month.'], ans:1,
  why:'<i lang="en">I’m having almost everything done by professionals</i>: <i lang="en">have something done</i> means you pay or arrange for someone else to do it. Priya’s own attempt at DIY (the shelf) ended badly.'},

 {kind:'Vocabulaire', h:'Work on the house',
  p:`<p>Building work, repairs and services: the vocabulary you need to deal with a builder, a landlord or a garage. Tap a line to hear it, then say it aloud.</p>`,
  mots:[['to do up a house','retaper, rénover une maison','They bought an old flat and did it up.'],['to have something done','faire faire quelque chose','We’re having the kitchen redone.'],['to get a quote','demander un devis','Always get three quotes before you choose a builder.'],['a builder','un entrepreneur, un maçon','The builders are coming on Monday.'],['a plumber / an electrician','un plombier / un électricien','We need a plumber: a pipe is leaking.'],['a decorator','un peintre en bâtiment','The decorator painted the living room in two days.'],['DIY','le bricolage','I’m hopeless at DIY.'],['to put up a shelf','poser une étagère','Can you help me put up these shelves?'],['to knock down a wall','abattre un mur','We knocked down a wall to make the kitchen bigger.'],['to get something serviced','faire réviser, faire entretenir','I get my boiler serviced every year.'],['to be behind schedule','être en retard sur le planning','The work is three weeks behind schedule.'],['to go over budget','dépasser le budget','The project went 20% over budget.'],['to cut corners','bâcler, rogner sur la qualité','Cheap builders often cut corners.'],['dodgy','douteux, pas fiable (familier)','The wiring looks a bit dodgy.'],['up and running','opérationnel, en marche','The new heating is up and running.']],
  note:'<b>Faux ami :</b> « un devis » = <i lang="en">a quote</i> (ou <i lang="en">an estimate</i>), jamais « a devis ». <i lang="en">DIY</i> = <i lang="en">do-it-yourself</i>. En américain : <i lang="en">fix up a house</i> (retaper), <i lang="en">a contractor</i> (un entrepreneur).'},

 {kind:'Pratique', h:'Recall: three quotes',
  p:'You’re telling a friend how you chose a plumber. <b>Question:</b> how do you say « Nous avons demandé trois devis avant de choisir un plombier. » ?', lab:'Your sentence',
  txt:A('We {got|asked for|requested} three {quotes|estimates} before {choosing|we chose|picking|we picked|selecting} a plumber.'),
  why:'<i lang="en">We got three quotes before choosing a plumber.</i> After <i lang="en">before</i>, use <i lang="en">-ing</i> (or a full clause: <i lang="en">before we chose</i>).'},

 {kind:'Grammaire', h:'The passive in every tense',
  p:`<p>Priya says: <i lang="en">The kitchen <b>is being redone</b>. The roof <b>has</b> already <b>been fixed</b>. It <b>should have been repaired</b> years ago.</i> What matters to her is the house, not who does the work. That’s the job of the <b>passive</b>: the object of the action becomes the subject of the sentence.</p>
<div class="def"><p><b>be (in the right tense) + past participle</b>. Only <i lang="en">be</i> changes; the participle stays the same.</p><ul><li>continuous: <i lang="en">is being redone</i>, <i lang="en">was being repaired</i></li><li>perfect: <i lang="en">has been fixed</i>, <i lang="en">had been sold</i></li><li>future: <i lang="en">will be finished</i>, <i lang="en">will have been finished</i></li><li>modals: <i lang="en">must be done</i>, <i lang="en">should have been repaired</i>, <i lang="en">must have been stolen</i></li><li>infinitive and <i lang="en">-ing</i>: <i lang="en">I want <b>to be told</b>. I hate <b>being interrupted</b>.</i></li></ul></div>
<div class="idea"><p>Use the passive when the doer is unknown, obvious or unimportant, or when you want to keep the same topic at the start of each sentence. Add <b>by</b> + agent only if it brings real information: <i lang="en">The house was designed <b>by</b> a famous architect</i>, but not <i lang="en">The thief was arrested by the police</i> (who else?).</p></div>
<div class="warn"><p><b>Pièges des francophones :</b> le français préfère souvent « on » : « on a réparé le toit » → <i lang="en">the roof has been repaired</i>. « On m’a dit de patienter » → <i lang="en">I was told to wait</i> : avec <i lang="en">tell, give, send, offer, show, ask</i>, c’est la personne qui devient sujet, et « I was said » n’existe pas. Les formes continues sont indispensables : « la cuisine est en train d’être refaite » = <i lang="en">is being redone</i>, pas « is redoing » (la cuisine ne refait rien&nbsp;!). Enfin, « je suis né » se dit toujours <i lang="en">I was born</i>, au passé.</p></div>`,
  audio:'The kitchen is being redone. The roof has already been fixed. It should have been repaired years ago. I was told to wait.'},

 {kind:'Méthode', h:'Turning an active sentence into the passive',
  p:`<p><b>When:</b> the object of the action is your real topic, or the doer is unknown. <b>Why it works:</b> the passive keeps the tense of the active verb but moves it onto <i lang="en">be</i>; the main verb becomes a past participle. <b>How:</b></p>
<ul><li>Find the object: it becomes the new subject.</li><li>Identify the tense or the modal of the active verb.</li><li>Put <i lang="en">be</i> in that tense (agreeing with the new subject), then add the past participle.</li><li>Keep <i lang="en">by</i> + agent only if it’s useful.</li></ul>`,
  demo:{enonce:'Make these sentences passive: 1) <i lang="en">They are renovating the station.</i> 2) <i lang="en">Someone should have warned the residents.</i> 3) <i lang="en">The council will have repaired the bridge by May.</i>',
   etapes:[{f:'1) Object: <i lang="en">the station</i>. Present continuous (<i lang="en">are renovating</i>) → <i lang="en">is being</i> + participle: <i lang="en">The station is being renovated.</i>',w:'<i lang="en">They</i> is vague, so there is no agent.'},
    {f:'2) Object: <i lang="en">the residents</i>. Past modal (<i lang="en">should have warned</i>) → <i lang="en">should have been</i> + participle: <i lang="en">The residents should have been warned.</i>',w:'After a modal, <i lang="en">be</i> stays in its base form; here, <i lang="en">have been</i>.'},
    {f:'3) Object: <i lang="en">the bridge</i>. Future perfect → <i lang="en">will have been</i> + participle: <i lang="en">The bridge will have been repaired by May.</i>',w:'<i lang="en">by May</i> is a deadline, not an agent. The council is obvious, so we drop it.'}],
   conclusion:'Same tense, new subject, <i lang="en">be</i> + participle: <i lang="en">is being renovated, should have been warned, will have been repaired</i>.'}},

 {kind:'Pratique', h:'Your turn: work in progress',
  p:'Rewrite in the passive, without an agent: <i lang="en">They are repairing the lift at the moment.</i> <b>Question:</b> what is happening to the lift?', lab:'Your sentence',
  txt:A('The lift is being repaired{ at the moment|}.','At the moment the lift is being repaired.'),
  why:'Present continuous → <i lang="en">is being</i> + participle: <i lang="en">The lift is being repaired at the moment.</i> (American English: <i lang="en">the elevator</i>.)'},

 {kind:'Pratique', h:'Your turn: a past modal in the passive',
  p:'Rewrite in the passive, without an agent: <i lang="en">Someone must have stolen the painting during the night.</i> <b>Question:</b> what must have happened to the painting?', lab:'Your sentence',
  txt:A('The painting must have been stolen{ during the night| in the night|}.','During the night the painting must have been stolen.'),
  why:'<i lang="en">must have stolen</i> → <i lang="en">must have been stolen</i>. A passive deduction: the modal and <i lang="en">have</i> stay, <i lang="en">been</i> is added before the participle.'},

 {kind:'Pratique', h:'Your turn: I was told',
  p:'At the hospital, a nurse asked you to wait in the corridor. <b>Question:</b> how do you say « On m’a dit d’attendre dans le couloir. » with a passive?', lab:'Your sentence',
  txt:A('I was {told|asked} to wait in the {corridor|hall|hallway}.'),
  why:'« On m’a dit de… » → <i lang="en">I was told to…</i>: the person becomes the subject. Never « I was said to wait ».'},

 {kind:'Grammaire', h:'Have something done, get something done',
  p:`<p>Priya says: <i lang="en">I’m having almost everything done by professionals… I had to get the tree cut down.</i> She doesn’t do the work herself: she <b>arranges</b> for someone else to do it. This is the <b>causative</b>.</p>
<div class="def"><p><b>have + object + past participle</b>: <i lang="en">I had the roof inspected.</i><br><b>get + object + past participle</b>: same meaning, a little more informal: <i lang="en">I need to get my hair cut.</i><br>Any tense is possible, carried by <i lang="en">have</i> or <i lang="en">get</i>: <i lang="en">We’re having the kitchen redone. I’ve just had my car serviced. You should get that cough checked.</i></p></div>
<div class="idea"><p>The same structure also describes something <b>bad that happened to you</b>, done by someone else: <i lang="en">I had my bike stolen. She had her bag searched at the airport.</i> With a person, use <b>have someone do</b> or <b>get someone to do</b>: <i lang="en">I’ll have the receptionist call you a taxi. I got my brother to help me move.</i> (<i lang="en">get</i> takes <i lang="en">to</i>; <i lang="en">have</i> doesn’t.)</p></div>
<div class="ex"><p><i lang="en">I cleaned my car.</i> (I did it myself.) / <i lang="en">I had my car cleaned.</i> (I paid someone.)</p></div>
<div class="warn"><p><b>Piège n°1 :</b> l’ordre des mots. <i lang="en">I had my car repaired</i> = j’ai fait réparer ma voiture ; <i lang="en">I had repaired my car</i> = j’avais réparé ma voiture (moi-même : c’est un plus-que-parfait). L’objet vient <b>avant</b> le participe. <b>Piège n°2 :</b> « se faire couper les cheveux » = <i lang="en">have / get <b>your</b> hair cut</i> ; on ne traduit pas « se » par <i lang="en">myself</i>. « Il s’est fait voler son portefeuille » = <i lang="en">He had his wallet stolen</i>.</p></div>`,
  audio:'I had the roof inspected. I need to get my hair cut. I had my bike stolen. I got my brother to help me move.'},

 {kind:'Pratique', h:'Your turn: at the hairdresser’s',
  p:'You didn’t cut your hair yourself: a hairdresser did it last Saturday. <b>Question:</b> how do you say this with the causative?', lab:'Your sentence',
  txt:A('I {had|got} my hair cut{ last Saturday|}.','Last Saturday I {had|got} my hair cut.'),
  why:'<i lang="en">I had my hair cut last Saturday</i> (or <i lang="en">got</i>). Object before participle. <i lang="en">I cut my hair</i> would mean you did it yourself.'},

 {kind:'Pratique', h:'Your turn: something bad that happened',
  p:'Translate into English with the causative. <b>Question:</b> how do you say « Il s’est fait voler son portefeuille dans le métro. » ?', lab:'Your sentence',
  txt:A('He {had|got} his wallet stolen {on|in} the {underground|Underground|tube|Tube|metro|subway}.'),
  why:'<i lang="en">He had his wallet stolen on the underground.</i> The causative also describes something done to you without your consent. In London, the underground is <i lang="en">the Tube</i>; in New York, <i lang="en">the subway</i>; in Paris, <i lang="en">the metro</i>.'},

 {kind:'Pratique', h:'Put the causative in order',
  p:'Tap the words in the right order. <b>Question:</b> what are the Taylors planning for their garden?',
  ordre:['They’re','going','to','have','the','old','fence','replaced','in','the','spring.'],
  alt:['In the spring they’re going to have the old fence replaced'],
  why:'<i lang="en">They’re going to have the old fence replaced in the spring.</i> <i lang="en">have</i> carries the tense (<i lang="en">going to have</i>), then object, then participle.'},

 {kind:'Grammaire', h:'It is said that… / He is thought to…',
  p:`<p>Priya says the house <i lang="en"><b>is said to be</b> the oldest in the village</i> and <i lang="en"><b>is thought to have been built</b> around 1750</i>. She is repeating what people believe, without saying who. News reports use these structures constantly.</p>
<div class="def"><p>With verbs such as <b>say, think, believe, know, report, expect, consider, claim</b>, there are two passive patterns:</p><ul><li><b>It is + participle + that…</b>: <i lang="en">It is said that the house is haunted.</i></li><li><b>Subject + is + participle + to-infinitive</b>: <i lang="en">The house is said to be haunted.</i></li></ul></div>
<div class="idea"><p>In the second pattern, the infinitive shows when the event happens compared with the moment of the belief: <b>to + verb</b> = same time (<i lang="en">He is thought to live abroad</i>); <b>to have + participle</b> = earlier (<i lang="en">He is thought to have left the country last year</i>); <b>to be + -ing</b> = in progress (<i lang="en">She is believed to be hiding in the hills</i>). For a belief in the past, put <i lang="en">be</i> in the past: <i lang="en">It was thought that the disease was caused by bad air.</i></p></div>
<div class="ex"><p><i lang="en">People believe the thief escaped through the roof.</i> → <i lang="en">It is believed that the thief escaped through the roof.</i> → <i lang="en">The thief is believed to have escaped through the roof.</i></p></div>
<div class="warn"><p><b>Pour les francophones :</b> c’est l’équivalent du conditionnel journalistique. « Le suspect <b>aurait fui</b> à l’étranger » = <i lang="en">The suspect <b>is believed to have fled</b> abroad</i> (et surtout pas « would have fled », qui veut dire tout autre chose). « Il serait millionnaire » = <i lang="en">He is said to be a millionaire</i>.</p></div>`,
  audio:'It is said that the house is haunted. The house is said to be haunted. The thief is believed to have escaped through the roof.'},

 {kind:'Méthode', h:'Reporting a belief in two ways',
  p:`<p><b>When:</b> you report a rumour, a belief or a news item without naming the source. <b>Why it works:</b> the <i lang="en">It</i> pattern keeps the original clause intact after <i lang="en">that</i>; the personal pattern moves its subject to the front, so its verb must become an infinitive, whose form shows the time. <b>How:</b></p>
<ul><li><i lang="en">It</i> pattern: <i lang="en">It is</i> (or <i lang="en">was</i>) + participle + <i lang="en">that</i> + the original clause.</li><li>Personal pattern: subject of the clause + <i lang="en">is / are / was / were</i> + participle + infinitive.</li><li>Compare the times: same time → <i lang="en">to + verb</i>; earlier → <i lang="en">to have + participle</i>; in progress → <i lang="en">to be + -ing</i>.</li></ul>`,
  demo:{enonce:'Report this with both patterns: <i lang="en">People say that the singer earned ten million pounds last year.</i>',
   etapes:[{f:'<i lang="en">It</i> pattern: <i lang="en">It is said that the singer earned ten million pounds last year.</i>',w:'<i lang="en">People say</i> → <i lang="en">It is said</i>; the <i lang="en">that</i>-clause doesn’t change.'},
    {f:'Personal pattern, new subject: <i lang="en">The singer is said…</i>',w:'The subject of the <i lang="en">that</i>-clause moves to the front; <i lang="en">is</i>, because people say it now.'},
    {f:'Time: the earning happened <b>before</b> the saying (last year) → <i lang="en">to have earned</i>.',w:'<i lang="en">to earn</i> would mean he earns that sort of money now, in general.'},
    {f:'<i lang="en">The singer is said to have earned ten million pounds last year.</i>',w:'Subject + <i lang="en">is said</i> + perfect infinitive.'}],
   conclusion:'<i lang="en">It is said that the singer earned £10 million last year. / The singer is said to have earned £10 million last year.</i>'}},

 {kind:'Pratique', h:'Your turn: the personal pattern',
  p:'Rewrite, starting with <i lang="en">The painting…</i>: <i lang="en">Experts believe that the painting was stolen in 1990.</i> <b>Question:</b> what do experts believe about the painting?', lab:'Your sentence',
  txt:A('The painting is believed to have been stolen in 1990.'),
  why:'The theft is earlier than the belief, and it’s already passive (<i lang="en">was stolen</i>) → perfect passive infinitive: <i lang="en">to have been stolen</i>.'},

 {kind:'Pratique', h:'Your turn: the It pattern',
  p:'Rewrite, starting with <i lang="en">It…</i>: <i lang="en">Analysts expect that house prices will fall next year.</i> <b>Question:</b> what is expected?', lab:'Your sentence',
  txt:A('It is expected that house prices will fall{ next year|}.'),
  why:'<i lang="en">Analysts expect</i> → <i lang="en">It is expected</i>; the <i lang="en">that</i>-clause stays as it is. Personal pattern: <i lang="en">House prices are expected to fall next year.</i>'},

 {kind:'Prononciation', h:'Weak forms: been, being, to have been',
  p:`<p>Passive sentences are full of small grammar words that native speakers say quickly. In British English, <i lang="en">been</i> is usually weak, /bɪn/, almost like <i lang="en">bin</i>; it only gets its long vowel, /biːn/, when it is stressed. <i lang="en">To have been</i> is squeezed into something like /təv bɪn/. The stress falls on the participle and the key nouns: <i lang="en">It’s been <b>fixed</b>. He’s thought to have <b>left</b> the <b>country</b>.</i></p>
<div class="idea"><p>In American English, <i lang="en">been</i> is often pronounced /bɪn/ too, or close to <i lang="en">Ben</i>. Whatever the accent, the participle is your key: if you hear <i lang="en">been</i> or <i lang="en">being</i> followed by a participle, it’s a passive.</p></div>
<div class="warn"><p><b>Pour les francophones :</b> ne confonds pas <i lang="en">been</i> (/bɪn/, court) et <i lang="en">being</i> (/ˈbiːɪŋ/, deux syllabes). <i lang="en">It has been painted</i> = c’est fait ; <i lang="en">It is being painted</i> = c’est en cours.</p></div>
<p>Listen, then say the sentence aloud.</p>`,
  dire:'The bridge is thought to have been built by the Romans.'},

 {kind:'Lecture', h:'Reading: saving the lido',
  p:`<p>Read this article from a local newspaper, then answer. You can also listen to it.</p>
<div class="blk" data-t="Halbury Lido to reopen after £4 million restoration"><p lang="en">After eight years behind locked gates, Halbury’s much-loved open-air swimming pool is finally due to reopen on 1 June, the council has announced.</p>
<p lang="en">The lido, which was built in 1936, is thought to have been one of the first heated outdoor pools in the country. It was closed in 2017 after cracks were found in the main pool. At the time, it was widely believed that the site would be sold to developers, and plans were even drawn up for a block of luxury flats.</p>
<p lang="en">That was before the Friends of Halbury Lido got involved. The campaign group, which was set up by a retired swimming teacher, collected more than 12,000 signatures and persuaded the council to have the building listed. Over the next five years, £4 million was raised, mostly through grants and local donations.</p>
<p lang="en">The restoration has not been without problems. The project was hit by rising costs and is reported to have gone almost £600,000 over budget. Work was held up for several months when the original 1930s tiles had to be removed one by one, cleaned and put back. “We could have had the pool relined in plastic in a fortnight,” says project manager Nadia Okafor, “but that would have been cutting corners. People wanted the lido they remembered.”</p>
<p lang="en">Not everyone is convinced. Some residents complain that tickets are expected to cost more than at the town’s indoor leisure centre. But for the campaigners, the reopening is a victory. “We were told again and again that it couldn’t be done,” says one of them. “This summer, we’ll be the first ones in the water.”</p></div>
<p><b>Question:</b> according to the article, why was the work delayed for several months?</p>`,
  audio:'Halbury Lido to reopen after four million pound restoration. After eight years behind locked gates, Halbury’s much-loved open-air swimming pool is finally due to reopen on 1 June, the council has announced. The lido, which was built in 1936, is thought to have been one of the first heated outdoor pools in the country. It was closed in 2017 after cracks were found in the main pool. At the time, it was widely believed that the site would be sold to developers, and plans were even drawn up for a block of luxury flats. That was before the Friends of Halbury Lido got involved. The campaign group, which was set up by a retired swimming teacher, collected more than 12,000 signatures and persuaded the council to have the building listed. Over the next five years, four million pounds was raised, mostly through grants and local donations. The restoration has not been without problems. The project was hit by rising costs and is reported to have gone almost six hundred thousand pounds over budget. Work was held up for several months when the original 1930s tiles had to be removed one by one, cleaned and put back. “We could have had the pool relined in plastic in a fortnight,” says project manager Nadia Okafor, “but that would have been cutting corners. People wanted the lido they remembered.” Not everyone is convinced. Some residents complain that tickets are expected to cost more than at the town’s indoor leisure centre. But for the campaigners, the reopening is a victory. “We were told again and again that it couldn’t be done,” says one of them. “This summer, we’ll be the first ones in the water.”',
  opts:['The council tried to sell the site to developers.','The campaign group couldn’t raise enough money.','The pool was relined in plastic, which took months.','The original tiles had to be removed, cleaned and put back one by one.'], ans:3,
  why:'<i lang="en">Work was held up for several months when the original 1930s tiles had to be removed one by one, cleaned and put back.</i> Relining the pool in plastic was rejected as <i lang="en">cutting corners</i>.'},

 {kind:'Dictée', h:'Dictation: a notice at work',
  p:'Listen and write exactly what you hear. You can replay it and use “Plus lentement”.',
  dictee:'The windows are being replaced, so the office will be closed until Friday.',
  why:'Two passives: present continuous (<i lang="en">are being replaced</i>) and future (<i lang="en">will be closed</i>). <i lang="en">being</i> has two syllables; <i lang="en">until</i> takes a single <i lang="en">l</i>.'},

 {kind:'Oral', h:'Speak: what’s been done?',
  p:`<p>Speak for about one minute about a place you know well: your home, your street, your school or your town. Say what has been done recently, what is being done now, what you have had done yourself, and what people say about the place.</p>`,
  oral:{modele:'In my town, a lot has changed in the last few years. The old station has been completely renovated, and the square in front of it is being turned into a pedestrian zone at the moment, so it’s a bit chaotic. A new bridge is going to be built next year. At home, we had the kitchen redone last summer, and I’ve just had a new boiler installed, which was expensive but necessary. The castle on the hill is said to be over eight hundred years old, and a famous queen is believed to have stayed there. Apparently, it was used as a prison during the war.',
   criteres:['I used the passive in at least three different tenses (has been, is being, will be…)','I used have or get something done for a service','I used It is said that… or is said / thought / believed to…','I left out the agent when it wasn’t important','I stressed the participles and kept been and being light']}},

 {kind:'Écriture', h:'Write: a complaint to the letting agency',
  p:'You rent a flat through a letting agency. Three weeks ago, the boiler broke down. A plumber came but didn’t fix it, and nobody has contacted you since. Write a formal email to the agency (about 180 words): explain what has happened, what has (or hasn’t) been done, what you were told, what you have had to do yourself, and what you expect now.',
  ecrire:{min:180, modele:'Dear Ms Collins,\n\nI am writing about the boiler in my flat at 12 Rose Court, which broke down on 3 March.\n\nI reported the problem the same day and was told that a plumber would be sent within 48 hours. A plumber did come on 6 March, but the boiler was not repaired: I was informed that a new part had to be ordered. Since then, I have not been contacted by anyone, and my emails and phone messages have not been answered.\n\nFor three weeks, the flat has not been properly heated, and I have had to buy two electric heaters. As the electric shower stopped working at the same time, I also had it checked by an electrician, whose bill is attached.\n\nI would be grateful if the boiler could be repaired by the end of next week at the latest. I would also like to be reimbursed for the heaters and the electrician’s visit, since these costs were caused by a fault that is the landlord’s responsibility.\n\nI look forward to hearing from you.\n\nYours sincerely,\n\nJulien Morel',
   criteres:[{t:'I used the present perfect passive (has not been repaired, have been answered…)', re:'\\b(has|have)( not|n’t|n\'t)? been \\w+(ed|en|t)\\b'},{t:'I used I was told or I was informed', re:'\\bI was (told|informed|promised|assured|asked)\\b'},{t:'I used have or get something done', re:'\\b(had|have|having|get|got|getting) (it|them|the \\w+|my \\w+) \\w+(ed|en)\\b'},'I explained the problem clearly, with dates',{t:'I used a formal opening and closing', re:'\\bdear\\b[\\s\\S]*\\byours (sincerely|faithfully)\\b'},'I asked politely for what I expect now (I would be grateful if…)']}},

 {kind:'Récapitulatif', h:'What to remember',
  p:`<div class="keep"><ul><li><b>Passive</b> = <i lang="en">be</i> in the right tense + past participle: <i lang="en">is being done, has been done, will have been done, should have been done, to be told, being interrupted</i>. Agent with <i lang="en">by</i> only if useful.</li><li>« on » → passive: <i lang="en">The roof has been repaired. I was told to wait</i> (never « I was said »). <i lang="en">I was born</i>, always in the past.</li><li>Method: object → subject, keep the tense on <i lang="en">be</i>, add the participle.</li><li><b>Causative</b>: <i lang="en">have / get + object + participle</i> (a service you arrange, or something bad done to you): <i lang="en">I had my hair cut. He had his wallet stolen.</i> With a person: <i lang="en">have someone do</i>, <i lang="en">get someone to do</i>. Don’t confuse with <i lang="en">I had repaired</i> (past perfect).</li><li><b>Reporting beliefs</b>: <i lang="en">It is said / thought / believed that…</i> or <i lang="en">He is said to + verb</i> (same time), <i lang="en">to have + participle</i> (earlier), <i lang="en">to be + -ing</i> (in progress). It translates the French journalistic conditional: « aurait fui » = <i lang="en">is believed to have fled</i>.</li><li>Pronunciation: weak <i lang="en">been</i> /bɪn/; <i lang="en">being</i> has two syllables.</li><li>Vocabulary: <i lang="en">do up, get a quote, a builder, DIY, put up a shelf, knock down a wall, get something serviced, behind schedule, over budget, cut corners, dodgy, up and running</i>.</li></ul></div>`},

 {kind:'Mission', h:'Mission: a message from the garage',
  p:'You left your car at the garage this morning for a service. Gary, the mechanic, has left you a voicemail. Listen to it, then answer the questions one by one. You can replay it at any time.',
  audio:'Hello, this is Gary from Westside Garage, calling about your car. It’s been serviced, and the oil has been changed. We’ve also had a look at the brakes: the front pads were badly worn, so they’ve been replaced, as you asked. The bad news is that the exhaust is damaged. To be honest, it should have been repaired months ago. We can get the new part delivered by Thursday, and if you want us to fit it, the car will be ready on Friday afternoon. The service and the brakes come to two hundred and forty pounds, and the exhaust would be another hundred and thirty. Give me a ring back when you can. Thanks, bye.', cache:true,
  parts:[
   {q:'a) What has already been done to the car?', opts:['The exhaust has been repaired and the oil changed.','Only the oil has been changed.','It has been serviced, and the front brake pads have been replaced.','The brakes have been checked but not replaced.'], ans:2, hint:'Listen for the verbs with <i lang="en">has been</i> and <i lang="en">have been</i>.', why:'<i lang="en">It’s been serviced, and the oil has been changed… the front pads… have been replaced.</i> The exhaust has not been repaired yet.'},
   {q:'b) If you also have the exhaust repaired, how much will you pay in total?', lab:'Total', unit:'£', ans:370, hint:'Add the price of the service and brakes to the price of the exhaust.', why:'£240 for the service and brakes + £130 for the exhaust = £370.'},
   {q:'c) Tell a friend what you’re going to do, with the causative: « Je vais faire réparer le pot d’échappement. »', lab:'Your sentence', txt:A('I am going to {have|get} the exhaust {repaired|fixed}.','I will {have|get} the exhaust {repaired|fixed}.','I am {having|getting} the exhaust {repaired|fixed}.'), hint:'<i lang="en">have</i> or <i lang="en">get</i> + object + past participle.', why:'<i lang="en">I’m going to have the exhaust repaired.</i> The object (<i lang="en">the exhaust</i>) comes before the participle.'},
   {q:'d) Rewrite this sentence in the passive, without an agent: <i lang="en">“We will fit the new part on Friday.”</i>', lab:'Your sentence', txt:A('The new part will be fitted on Friday.','On Friday the new part will be fitted.'), hint:'Future passive: <i lang="en">will be</i> + participle.', why:'<i lang="en">The new part will be fitted on Friday.</i> The garage is obvious, so no <i lang="en">by</i>.'}],
  sol:'<p lang="en">The car has been serviced, the oil has been changed and the front brake pads have been replaced. The exhaust is damaged and should have been repaired months ago. If you have it repaired, the car will be ready on Friday afternoon, and the total will be £240 + £130 = £370.</p><p>Causative: <i lang="en">I’m going to have the exhaust repaired.</i> Passive: <i lang="en">The new part will be fitted on Friday.</i></p>'},

 {kind:'Mission', h:'Mission: the vanished masterpiece',
  p:`<p>Read this news report, then answer the questions.</p>
<div class="blk" data-t="Masterpiece vanishes from country house"><p lang="en">A painting worth an estimated £3 million has disappeared from Ashleigh Manor, a country house in Dorset that is open to the public. <i>The Harvest Moon</i>, by the eighteenth-century artist Thomas Fairley, was last seen by a guide on Sunday afternoon. According to the police, there was no sign of a break-in, and the alarm system is reported to have been switched off for maintenance that weekend. The thieves are thought to have known the house well. It is also believed that the painting was cut from its frame on the spot, as the empty frame was found in a nearby wood on Tuesday. A 45-year-old man has been questioned and released. The owners, who had the painting valued only last year, say they are devastated. A reward is expected to be offered later this week.</p></div>`,
  parts:[
   {q:'a) What does the report suggest about the thieves?', opts:['They broke a window to get in.','They were seen by a guide on Sunday.','They probably knew the house well.','They took the painting away in its frame.'], ans:2, hint:'Look for <i lang="en">are thought to…</i>', why:'<i lang="en">The thieves are thought to have known the house well.</i> There was no break-in, and the frame was found empty.'},
   {q:'b) Which phrase from the report corresponds to the French « Le système d’alarme aurait été coupé » ?', opts:['The alarm system would have been switched off.','The alarm system had switched off.','The alarm system is reported to have been switched off.','The alarm system has them switched off.'], ans:2, hint:'The French journalistic conditional becomes a reporting verb in the passive.', why:'« aurait été coupé » = <i lang="en">is reported to have been switched off</i>: a perfect passive infinitive, because the switching off happened before the report.'},
   {q:'c) Rewrite with the personal pattern, starting with <i lang="en">The painting…</i>: <i lang="en">“It is believed that the painting was cut from its frame on the spot.”</i>', lab:'Your sentence', txt:A('The painting is believed to have been cut from its frame{ on the spot|}.'), hint:'The cutting happened before the belief, and it’s passive: <i lang="en">to have been</i> + participle.', why:'<i lang="en">The painting is believed to have been cut from its frame on the spot.</i>'},
   {q:'d) Rewrite with the <i lang="en">It</i> pattern: <i lang="en">“The thieves are thought to have known the house well.”</i>', lab:'Your sentence', txt:A('It is thought that the thieves {knew|had known} the house well.','It is thought the thieves {knew|had known} the house well.'), hint:'<i lang="en">It is thought that</i> + a full clause in the past.', why:'<i lang="en">It is thought that the thieves knew the house well.</i> <i lang="en">to have known</i> becomes a past tense in the <i lang="en">that</i>-clause.'},
   {q:'e) The police are going to ask experts to examine the empty frame. Write this with the causative <i lang="en">have</i>, starting with <i lang="en">The police are going to…</i>', lab:'Your sentence', txt:A('The police are going to have the {empty |}frame examined{ by experts| by an expert|}.'), hint:'<i lang="en">have</i> + object + past participle.', why:'<i lang="en">The police are going to have the empty frame examined (by experts).</i> Here the agent is useful information.'}],
  sol:'<p lang="en">The painting disappeared from Ashleigh Manor without a break-in. The thieves are thought to have known the house well, and the alarm is reported to have been switched off. The painting is believed to have been cut from its frame on the spot.</p><p>« aurait été coupé » = <i lang="en">is reported to have been switched off</i>. <i lang="en">It</i> pattern: <i lang="en">It is thought that the thieves knew the house well.</i> Causative: <i lang="en">The police are going to have the empty frame examined.</i></p>'},
]},
);
})();
